insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 4, 'ബഹുദൈവാരാധകരെ അറേബ്യൻ ഉപഭൂഖണ്ഡത്തിൽനിന്ന് പുറത്താക്കണമെന്ന നബി(സ)യുടെ വസ്വിയ്യത്ത്', 'بَابٌ: وَصِيَّةُ النَّبِيِّ (صلعم) بِإِخْرَاجِ الْمُشْرِكِينَ مِنْ جَزِيرَةِ الْعَرَبِ', 686 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
