insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 6, 'ജീവിതകാലത്ത് പിശുക്കുകയും മരണസമയത്ത് ധൂർത്തടിക്കുകയും ചെയ്യുന്നതിനുള്ള നിരോധനം', 'بَابٌ: النَّهْيُ عَنِ الْإِمْسَاكِ فِي الْحَيَاةِ وَالتَّبْذِيرِ عِنْدَ الْمَوْتِ', 689 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
