insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 8, 'വസ്വിയ്യത്തിൽ ഇടപെടൽ', 'بَابٌ: مَا جَاءَ فِي الدُّخُولِ فِي الْوَصَايَا', 692 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 9, 'മാതാപിതാക്കൾക്കും അടുത്ത കുടുംബങ്ങൾക്കും വസ്വിയ്യത്ത് ചെയ്യണമെന്നതിനെ ദുർബ്ബലപ്പെടുത്തൽ', 'بَابٌ: مَا جَاءَ فِي نَسْخِ الْوَصِيَّةِ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ', 692 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
