insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 11, 'അടുത്ത കുടുംബത്തിനു വേണ്ടി വസ്വിയ്യത്ത് ചെയ്താൽ', 'بَابٌ: إِذَا أَوْصَى لِعَشِيرَتِهِ الْأَقْرَبِينَ', 693 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 12, 'അനന്തരം വീതിക്കും മുമ്പേ കടം വീട്ടൽ', 'بَابٌ: قَضَاءُ الدَّيْنِ قَبْلَ الْمِيرَاثِ', 694 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 13, 'വസ്വിയ്യത്തിനു മുമ്പ് കടം പരിഗണിക്കപ്പെടണം', 'بَابٌ: الدَّيْنُ قَبْلَ الْوَصِيَّةِ', 697 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 14, 'ദാനം നൽകിയ വസ്തു വസ്വിയ്യത്തായോ അനന്തരമായോ ഒരുത്തന് ലഭിച്ചാൽ', 'بَابٌ: فِي الرَّجُلِ يَهَبُ الْهِبَةَ ثُمَّ يُوصَي لَهُ بِهَا أَوْ يَرِثُهَا', 697 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 15, 'മരണപ്പെട്ടയാൾക്കുവേണ്ടി ദാനം ചെയ്യുന്നതിന്റെ ശ്രേഷ്ഠത', 'بَابٌ: فَضْلُ الصَّدَقَةِ عَنِ الْمَيِّتِ', 698 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 16, 'വസ്വിയ്യത്ത് ചെയ്യാതെ മരിച്ചയാളുടെ പേരിൽ ദാനം ചെയ്യൽ', 'بَابٌ: مَا جَاءَ فِيمَنْ مَاتَ عَنْ غَيْرِ وَصِيَّةٍ يُتَصَدَّقُ عَنْهُ', 699 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 17, 'മുസ്ലിമായ പിന്തുടർച്ചക്കാരനുള്ള സത്യനിഷേധിയുടെ വസ്വിയ്യത്ത്', 'بَابٌ: مَا جَاءَ فِي وَصِيَّةِ الْحَرْبِيِّ يُسْلِمُ وَلِيُّهُ', 700 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 18, 'അടിമയുടെ പിന്തുടർച്ചാവകാശം അവനെ മോചിപ്പിച്ചവന്നാണ്', 'بَابٌ: الْوَلَاءُ لِمَنْ أَعْتَقَ', 700 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 19, 'അനാഥന്റെ സ്വത്തിൽ വസ്വിയ്യത്ത് ചെയ്യപ്പെട്ടവനുള്ള അവകാശം', 'بَابٌ: مَا لِلْوَصِيِّ مِنْ مَالِ الْيَتِيمِ', 701 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 20, 'എപ്പോഴാണ് അനാഥത്വം നീങ്ങുക', 'بَابٌ: مَا جَاءَ مَتَى يَنْقَطِعُ الْيُتْمُ', 702 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 21, 'അനാഥന്റെ മുതൽ ഭക്ഷിക്കുന്നതിന്റെ കാഠിന്യം', 'بَابٌ: مَا جَاءَ فِي التَّشْدِيدِ فِي أَكْلِ مَالِ الْيَتِيمِ', 702 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 22, 'കഫൻപുട മൊത്തം സ്വത്തിൽനിന്നാണെടുക്കേണ്ടത് എന്നതിനുള്ള തെളിവ്', 'بَابٌ: مَا جَاءَ فِي الدَّلِيلِ عَلَى أَنَّ الْكَفَنَ مِنْ جَمِيعِ الْمَالِ', 703 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
insert into chapters (book_id, chapter_no, title_ml, title_ar, start_page) select id, 23, '''നിങ്ങളിലൊരാൾക്ക് മരണമാസന്നമായാൽ നിങ്ങൾക്കിടയിലെ സാക്ഷിത്വം'' എന്ന സൂക്തം', 'بَابٌ: فِي قَوْلِهِ تَعَالَى: {شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ ...}', 703 from books where volume_id=3 and book_no=12 on conflict (book_id, chapter_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, chapters.title_ar), start_page=excluded.start_page;
