insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَيُّ الصَّدَقَةِ أَعْظَمُ أَجْرًا؟ قَالَ: "أَنْ تَصدَّقَ وَأَنْتَ صَحِيحٌ شَحِيحٌ، تَخْشَى الْفَقْرَ وَتَأْمُلُ الْبَقَاءَ، وَلَا تُمْهِلْ حَتَّى إِذَا بَلَغَتِ الْحُلْقُومَ قُلْتَ: لِفُلَانٍ كَذَا، وَقَدْ كَانَ لِفُلَانٍ". (ق,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ അടുത്ത് ഒരാൾ വന്ന് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഏറ്റവും മഹത്തായ പ്രതിഫലമുള്ള ദാനം ഏതാണ്? അവിടന്ന് പറഞ്ഞു: "സാശ്വതമായ ജീവിതത്തെ നീ കൊതിക്കുകയും ദാരിദ്ര്യത്തെ ഭയക്കുകയും ചെയ്യുന്ന സമയത്ത്, നീ ആരോഗ്യവാനും പിശുക്കനുമാകുന്ന അവസ്ഥയിൽ, നൽകുന്ന ദാനമാണ്. ആത്മാവ് തൊണ്ടക്കുഴിയിലെത്തുകയും, ഇന്നവന് ഇത്ര നൽകുക എന്ന് നീ പറയുകയും എന്നാൽ അത് മറ്റുള്ളവർക്ക് അവകാശപ്പെട്ടതാവുകയും ചെയ്യുന്ന സമയം വരെ നീ പിന്തിപ്പിക്കരുത്." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 683, 683, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّكُمْ مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالِهِ". قَالُوا: يَا رَسُولَ اللَّهِ، مَا مِنَّا مِنْ أَحَدٍ إِلَّا مَالُهُ أَحَبُّ إِلَيْهِ مِنْ مَالِ وَارِثِهِ. قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اعْلَمُوا أَنَّهُ لَيْسَ مِنْكُمْ مِنْ أَحَدٍ إِلَّا مَالُ وَارِثِهِ أَحَبُّ إِلَيْهِ مِنْ مَالِهِ. مَالُكَ مَا قَدَّمْتَ، وَمَالُ وَارِثِكَ مَا أَخَّرْتَ". (ن)', 'അബ്ദുല്ല(റ): റസൂൽ(സ) ചോദിച്ചു: "തന്റെ സമ്പത്തിനേക്കാൾ തന്റെ അനന്തരാവാകാശിയുടെ സമ്പത്ത് ഇഷ്ടപ്പെടുന്നവർ നിങ്ങളിലാരുണ്ട്?" അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, തന്റെ അനന്തരാവകാശിയുടെ സ്വത്തിനേക്കാൾ സ്വന്തം സ്വത്ത് ഇഷ്ടപ്പെടുന്നവരല്ലാത്ത ഒരാളും ഞങ്ങളിലില്ല. റസൂൽ പറഞ്ഞു: "നിങ്ങളറിയുക, തന്റെ സ്വത്തിനേക്കാൾ തന്റെ അനന്തരാവാകാശിയുടെ സ്വത്ത് ഇഷ്ടപ്പെടുന്നവരല്ലാതെ ഒരാളും നിങ്ങളിലില്ല. നീ ദാനമായി നൽകിയതാണ് നിന്റെ സ്വത്ത്. നീ പിന്തിപ്പിച്ച് വെച്ചതാണ് നിന്റെ അനന്തരാവകാശിയുടെ സ്വത്ത്." (ന)', 'عَبْدِ اللَّهِ', 'അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 683, 683, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَبْدِ اللهِ بْنِ الشَّخِيرِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: {أَلْهَاكُمُ التَّكَاثُرُ حَتَّى زُرْتُمُ الْمَقَابِرَ} قَالَ: "يَقُولُ ابْنُ آدَمَ: مَالِي مَالِي، وَإِنَّمَا مَالُكَ مَا أَكَلْتَ فَأَفْنَيْتَ، أَوْ لَبِسْتَ فَأَبْلَيْتَ، أَوْ تَصَدَّقْتَ فَأَمْضَيْتَ". (ن)', 'അബ്ദുല്ലാഹിബ്നുശ്ശഖീർ(റ): ''ധാരാളിത്വത്തിനുള്ള മാത്സര്യം നിങ്ങളെ അശ്രദ്ധരാക്കിയിരിക്കുന്നു, നിങ്ങൾ ഖബറിടങ്ങൾ സന്ദർശിക്കുന്നതുവരെ.'' എന്ന സൂക്തത്തെക്കുറിച്ച് നബി(സ) പറഞ്ഞു: "എന്റെ സ്വത്ത്, എന്റെ സ്വത്ത് എന്ന് ആദം സന്തതി പറയും. നിശ്ചയം നീ തിന്ന് നശിപ്പിക്കുകയും, നീ ധരിച്ച് നുരുമ്പിപ്പിക്കുകയും, നീ ദാനം ചെയ്ത് നടപ്പിലാക്കുകയും ചെയ്തത് മാത്രമാണ് നിന്റെ സമ്പത്ത്." (ന)', 'عَبْدِ اللهِ بْنِ الشَّخِيرِ', 'അബ്ദുല്ലാഹിബ്നുശ്ശഖീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 683, 683, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي حُبَيْبَةَ الطَّائِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَوْصَى رَجُلٌ بِدَنَانِيرَ فِي سَبِيلِ اللَّهِ، فَسُئِلَ أَبُو الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ، فَحَدَّثَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَثَلُ الَّذِي يُعْتِقُ أَوْ يَتَصَدَّقُ عِنْدَ مَوْتِهِ مَثَلُ الَّذِي يُهْدِي بَعْدَمَا يَشْبَعُ". (ن)', 'അബൂഹുബൈബതിത്ത്വാഈ(റ): ഒരാൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ കുറേ ദീനാറുകൾ വസ്വിയ്യത് ചെയ്തു. അങ്ങനെ അതേക്കുറിച്ച് അബുദ്ദർദാഅ്(റ)വിനോട് ചോദിക്കപ്പെടുകയുണ്ടായി. അപ്പോൾ അദ്ദേഹം നബി(സ)യിൽ നിന്നുള്ള ഹദീസ് പറഞ്ഞു: അവിടന്ന് പറഞ്ഞു: "വയർ നിറഞ്ഞ ശേഷം ഹദ്യ (സമ്മാനം) നൽകുന്നവനെപ്പോലെയാണ് മരണ സമയത്ത് ദാനം ചെയ്യുകയോ, അടിമയെ മോചിപ്പിക്കുകയോ ചെയ്യുന്നവന്റെ ഉപമ." (ന)', 'أَبِي حُبَيْبَةَ الطَّائِيِّ', 'അബൂഹുബൈബതിത്ത്വാഈ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا حَقُّ امْرِئٍ مُسْلِمٍ، لَهُ شَيْءٌ يُوصَى فِيهِ، أَنْ يَبِيتَ لَيْلَتَيْنِ – فِي رِوَايَةٍ: فَيَبِيتُ ثَلَاثَ لَيَالٍ – إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ". (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "വസ്വിയ്യത് ചെയ്യാവുന്ന വല്ലതും കൈവശമുള്ള മുസ്ലിമായ ഒരാൾക്കും തന്നെ, തന്റെ വസ്വിയ്യത് തന്റെ പക്കൽ എഴുതിവെക്കപ്പെട്ടിട്ടല്ലാതെ രണ്ടു രാത്രി - മറ്റൊരു നിവേദനം: മൂന്നു രാത്രി - കഴിയാൻ അവകാശമില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=5), 1, null, 'മറ്റൊരു നിവേദനം: മൂന്നു രാത്രി - കഴിയാൻ അവകാശമില്ല." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا حَقُّ امْرِئٍ مُسْلِمٍ تَمُرُّ عَلَيْهِ ثَلَاثُ لَيَالٍ إِلَّا وَعِنْدَهُ وَصِيَّتُهُ". قَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: مَا مَرَّتْ عَلَيَّ مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ ذَلِكَ إِلَّا وَعِنْدِي وَصِيَّتِي. (م,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറഞ്ഞു: "തന്റെ വസ്വിയ്യത്ത് തന്റെ കൂടെയുണ്ടായിക്കൊണ്ടല്ലാതെ, മൂന്ന് രാത്രികൾ കടന്നുപോകൽ ഒരു മുസ്ലിമിനും യോജിച്ചതല്ല." അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) അത് പറഞ്ഞത് ഞാൻ കേട്ടതുതൊട്ട് എന്റെ പക്കൽ എന്റെ വസ്വിയ്യത്തില്ലാതെ ഒരു രാത്രിയും കടന്നുപോയിട്ടില്ല. (മു,ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمَحْرُومُ مَنْ حُرِمَ وَصِيَّتَهُ". [ز: فِي إِسْنَادِهِ ضَعِيفٌ] (جه)', 'അനസുബ്നുമാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ വസ്വിയ്യത്ത് തഴയപ്പെട്ടവനാണ് നിർഭാഗ്യവാൻ." ഇതിന്റെ സനദിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ ضَعِيفٌ', null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ مَاتَ عَلَى وَصِيَّةٍ مَاتَ عَلَى سَبِيلٍ وَسُنَّةٍ، وَمَاتَ عَلَى تُقًى وَشَهَادَةٍ، وَمَاتَ مَغْفُورًا لَهُ". [ز: فِي إِسْنَادِهِ مُدَلِّسٌ عَنْعَنَهُ] (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു വസ്വിയ്യത്ത് ചെയ്ത് മരിച്ചാൽ അവൻ (ദൈവിക) മാർഗ്ഗത്തിലും (പ്രവാചക) ചര്യയിലുമായിട്ടാണ് മരണപ്പെട്ടത്. അവൻ ഭക്തിയിലും സാക്ഷ്യത്തിലുമാണ് മരണപ്പെട്ടത്. പാപങ്ങൾ പൊറുക്കപ്പെട്ടവനായാണ് അവൻ മരണപ്പെട്ടത്." ഇതിന്റെ സനദിൽ അൻഅൻ ചെയ്തു പറഞ്ഞ ഒരു മുദല്ലിസുണ്ട്. (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ مُدَلِّسٌ عَنْعَنَهُ', null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا تَرَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِينَارًا وَلَا دِرْهَمًا، وَلَا شَاةً وَلَا بَعِيرًا، وَلَا أَوْصَى بِشَيْءٍ. (م,د,ن,جه)', 'ആഇശ(റ): റസൂൽ(സ) ഒരു ദീനാറോ ദിർഹമോ ഒരു ആടോ ഒട്ടകമോ ഒന്നും അവശേഷിപ്പിച്ചിരുന്നില്ല. അവിടന്ന് ഒന്നുംതന്നെ വസ്വിയ്യത്ത് ചെയ്തിട്ടുമില്ലായിരുന്നു. (മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ طَلْحَةَ بْنِ مُصَرِّفٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ ابْنَ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا: هَلْ أَوْصَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: لَا، قُلْتُ: فَلِمَ كُتِبَ عَلَى الْمُسْلِمِينَ الْوَصِيَّةُ، أَوْ: فَلِمَ أُمِرُوا بِالْوَصِيَّةِ؟ قَالَ: أَوْصَى بِكِتَابِ اللَّهِ عَزَّ وَجَلَّ. (ق,ت,ن,جه)', 'ത്വൽഹതുബ്നു മുസ്വർറിഫ്(റ): അബ്ദുല്ലഹിബ്നു അബീഔഫാ(റ)വിനോട് ഞാൻ ചോദിച്ചു: റസൂൽ(സ) വല്ലതും വസ്വിയ്യത്ത് ചെയ്തിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല. ഞാൻ ചോദിച്ചു: പിന്നെയെന്തിനാണ് വസ്വിയ്യത്ത് ചെയ്യൽ മുസ്ലിംകൾക്ക് നിർബന്ധമാക്കപ്പെട്ടത്? - അല്ലെങ്കിൽ: പിന്നെയെന്തിനാണ് അവർ വസ്വിയ്യത്ത് ചെയ്യാൻ കൽപിക്കപ്പെട്ടത്? - അദ്ദേഹം പറഞ്ഞു: മഹോന്നതനായ അല്ലാഹുവിന്റെ ഗ്രന്ഥം കൊണ്ട് അവിടന്ന് വസ്വിയ്യത്ത് ചെയ്തിട്ടുണ്ട്. (ബു,മു,തു,ന,ജ)', 'طَلْحَةَ بْنِ مُصَرِّفٍ', 'ത്വൽഹതുബ്നു മുസ്വർറിഫ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ عَامَّةُ وَصِيَّةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ حَضَرَتْهُ الْوَفَاةُ، وَهُوَ يُغَرْغِرُ بِنَفْسِهِ: "الصَّلَاةَ، وَمَا مَلَكَتْ أَيْمَانُكُمْ". (جه)', 'അനസുബ്നു മാലിക്(റ): വഫാതിന്റെ സമയത്ത് റസൂൽ(സ)യുടെ ശ്വാസം ഇടറിക്കൊണ്ടിരിക്കുമ്പോൾ അവിടത്തെ പൊതുവായുള്ള വസ്വിയ്യത്ത് ഇപ്രകാരമായിരുന്നു: "നിസ്കാരത്തെയും നിങ്ങൾ ഉടമപ്പെടുത്തിയതിനെയും സൂക്ഷിക്കുക." (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ آخِرُ كَلَامِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الصَّلَاةَ وَمَا مَلَكَتْ أَيْمَانُكُمْ". (د,جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): നബി(സ)യുടെ അവസാനത്തെ വചനം ഇതായിരുന്നു: "നിസ്കാരത്തെയും നിങ്ങൾ ഉടമപ്പെടുത്തിയതിനെയും സൂക്ഷിക്കുക." (ദ,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: تُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَيْسَ عِنْدَهُ أَحَدٌ غَيْرِي. قَالَتْ: وَدَعَا بِالطَّسْتِ. (ن)', 'ആഇശ(റ): റസൂൽ(സ) വഫാതാകുമ്പോൾ ഞാനല്ലാത്ത ഒരാളും അവിടത്തെ സമീപത്തുണ്ടായിരുന്നില്ല. മഹതി പറഞ്ഞു: അവിടന്ന് ഒരു കോളാമ്പി കൊണ്ടുവരാൻ ആവശ്യപ്പെട്ടു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ الْأَسْوَدِ بْنِ يَزِيدٍ قَالَ: ذَكَرُوا عِنْدَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ كَانَ وَصِيًّا، فَقَالَتْ: مَتَى أَوْصَى إِلَيْهِ؟ وَقَدْ كُنْتُ مُسْنِدَتَهُ إِلَى صَدْرِي – أَوْ قَالَتْ: حَجْرِي – فَدَعَا بِالطَّسْتِ، فَلَقَدِ انْخَنَثَ فِي حَجْرِي، فَمَا شَعَرْتُ أَنَّهُ قَدْ مَاتَ، فَمَتَى أَوْصَى إِلَيْهِ؟ (م)', 'അസ്വദുബ്നു യസീദ്(റ): ആഇശ(റ)വിന്റെ സമീപത്തുവെച്ച് ജനങ്ങൾ പറഞ്ഞു: അലി(റ) (നബി(സ)യുടെ) വസ്വിയ്യ് (വസ്വിയ്യത്ത് ഏൽപിക്കപ്പെട്ട വ്യക്തി) ആയിരുന്നു. അപ്പോൾ മഹതി ചോദിച്ചു: എപ്പോഴാണ് അവിടന്ന് അദ്ദേഹത്തോട് വസ്വിയ്യത്ത് ചെയ്തത്? എന്റെ നെഞ്ചിലേക്ക് - അല്ലെങ്കിൽ: എന്റെ മടിയിലേക്ക് - അവിടന്ന് ചാരിയിരിക്കുകയായിരുന്നു. അവിടന്ന് ഒരു കോളാമ്പി കൊണ്ടുവരാൻ ആവശ്യപ്പെട്ടു. ഉടൻ അവിടന്ന് എന്റെ മടിയിലേക്ക് വീണ് കഴിഞ്ഞിരുന്നു. അവിടന്ന് വഫാതായത് ഞാൻ അറിഞ്ഞതുപോലുമില്ല. പിന്നെ എപ്പോഴാണ് അവിടന്ന് അദ്ദേഹത്തോട് വസ്വിയ്യത്ത് ചെയ്തത്? (മു)', 'الْأَسْوَدِ بْنِ يَزِيدٍ قَالَ', 'അസ്വദുബ്നു യസീദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: يَقُولُونَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْصَى إِلَى عَلِيٍّ رَضِيَ اللهُ عَنْهُ، لَقَدْ دَعَا بِالطَّسْتِ لِيَبُولَ فِيهَا، فَانْخَنَثَتْ نَفْسُهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَا أَشْعُرُ، فَإِلَى مَنْ أَوْصَى. (ن)', 'ആഇശ(റ): റസൂൽ(സ) അലി(റ)വിനോട് വസ്വിയ്യത്ത് ചെയ്തിട്ടുണ്ടെന്ന് അവർ പറയുന്നു. അവിടന്ന് മൂത്രമൊഴിക്കുന്നതിനുവേണ്ടി കോളാമ്പി കൊണ്ടുവരാൻ കൽപിച്ചു. ഉടൻ ഞാൻ പോലും അറിയാതെ അവിടത്തെ തിരുശരീരം വീണു. പിന്നെയാരോടാണ് അവിടന്ന് വസ്വിയ്യത്ത് ചെയ്തത്? (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ عَمْرِو بْنِ الْحَارِثِ رَضِيَ اللهُ عَنْهُ قَالَ: مَا تَرَكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِينَارًا وَلَا دِرْهَمًا وَلَا عَبْدًا وَلَا أَمَةً، إِلَّا بَغْلَتَهُ الشَّهْبَاءَ – وَفِي رِوَايَةٍ: الْبَيْضَاءَ – الَّتِي كَانَ يَرْكَبُهَا، وَسِلَاحَهُ، وَأَرْضًا جَعَلَهَا – تَرَكَهَا – فِي سَبِيلِ اللَّهِ صَدَقَةً. (خ,ن)', 'അംറുബ്നുൽ ഹാരിസ്(റ): റസൂൽ(സ) സവാരിചെയ്യാറുണ്ടായിരുന്ന വെളുത്ത ഒരു കോവർകഴുതയും, അവിടത്തെ ആയുധവും, അവിടന്ന് അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലേക്കുള്ള ദാനമായി നിശ്ചയിച്ചിട്ടുണ്ടായിരുന്ന ഒരു ഭൂമിയുമല്ലാതെ ഒരു അടിമയെയോ അടിമസ്ത്രീയെയോ ഒരു ദീനാറോ ദിർഹമോ റസൂൽ(സ) ബാക്കിവെച്ചിട്ടുണ്ടായിരുന്നില്ല. (ബു,ന)', 'عَمْرِو بْنِ الْحَارِثِ', 'അംറുബ്നുൽ ഹാരിസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=16), 1, 'وَفِي رِوَايَةٍ: الْبَيْضَاءَ – الَّتِي كَانَ يَرْكَبُهَا، وَسِلَاحَهُ، وَأَرْضًا جَعَلَهَا – تَرَكَهَا – فِي سَبِيلِ اللَّهِ صَدَقَةً. (خ,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقْتَسِمُ وَرَثَتِي دِينَارًا وَلَا دِرْهَمًا، مَا تَرَكْتُ بَعْدَ نَفَقَةِ نِسَائِي وَمَئُونَةِ عَامِلِي فَهُوَ صَدَقَةٌ". (خ)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ദീനാറും ദിർഹമുമായി എന്റെ അനന്തരസ്വത്തിനെ വീതിക്കരുത്. ഞാൻ ഉപേക്ഷിച്ചിടുന്നതിൽ നിന്ന് എന്റെ ഭാര്യമാർക്കുള്ള ചെലവും എന്റെ ജോലിക്കാരുടെ കൂലിയും കഴിച്ചുള്ളതെല്ലാം ദാനമാണ്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ ابْنُ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: يَوْمُ الْخَمِيسِ وَمَا يَوْمُ الْخَمِيسِ، ثُمَّ بَكَى حَتَّى بَلَّ دَمْعُهُ الْحَصَى، فَقُلْتُ: يَا ابْنَ عَبَّاسٍ وَمَا يَوْمُ الْخَمِيسِ؟ قَالَ: اشْتَدَّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجَعُهُ فَقَالَ: "ائْتُونِي أَكْتُبْ لَكُمْ كِتَابًا لَا تَضِلُّوا بَعْدِي". فَتَنَازَعُوا، وَمَا يَنْبَغِي عِنْدَ نَبِيٍّ تَنَازُعٌ، وَقَالُوا: مَا شَأْنُهُ أَهَجَرَ؟ اسْتَفْهِمُوهُ، قَالَ: "دَعُونِي، فَالَّذِي أَنَا فِيهِ خَيْرٌ، أُوصِيكُمْ بِثَلَاثٍ: أَخْرِجُوا الْمُشْرِكِينَ مِنْ جَزِيرَةِ الْعَرَبِ، وَأَجِيزُوا الْوَفْدَ بِنَحْوِ مَا كُنْتُ أُجِيزُهُمْ". قَالَ: وَسَكَتَ عَنِ الثَّالِثَةِ، أَوْ قَالَهَا فَأُنْسِيتُهَا. (م)', 'സഈദുബ്നു ജൂബൈർ(റ): ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: വ്യാഴാഴ്ച ദിവസം, എന്തൊരു ഭയങ്കര ദിവസമാണ് വ്യാഴാഴ്ച. ശേഷം അദ്ദേഹം ചരലുകൾ നനക്കുമാർ കണ്ണിരോടെ കരഞ്ഞു. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഓ ഇബ്നുഅബ്ബാസ്, എന്താണ് വ്യാഴാഴ്ച ദിവസം? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)ക്ക് വേദന ശക്തമായി, അവിടന്ന് പറഞ്ഞു: "നിങ്ങൾ എന്റെ അടുത്ത് വരിക, ഞാൻ നിങ്ങൾക്കൊരു എഴുത്ത് എഴുതിത്തരാം, എങ്കിൽ എനിക്കുശേഷം നിങ്ങൾ പിഴക്കുകയില്ല." അപ്പോൾ അവർ തർക്കിച്ചു. ഒരു പ്രവാചകന്റെ മുന്നിൽ തർക്കിക്കാൻ പാടില്ല. അവർ പറഞ്ഞു: അവിടത്തെ അവസ്ഥയെന്താണ്? അവിടത്തെ സംസാരം (രോഗത്താൽ) പകർച്ചപ്പെട്ടിരിക്കുന്നു. അവിടത്തോട് വിശദീകരണം ചോദിക്കൂ. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളെന്നെ വിട്ടേക്കുക, ഇപ്പോൾ ഞാൻ നിലകൊള്ളുന്നത് നല്ല അവസ്ഥയിലാണ്. ഞാൻ നിങ്ങളോട് മൂന്ന് കാര്യങ്ങൾ വസ്വിയ്യത്ത് ചെയ്യുന്നു: അറേബ്യൻ ഉപഭൂഖണ്ഡത്തിൽ നിന്നും ബഹുദൈവാരാധകരെ നിങ്ങൾ പുറത്താക്കുക, നിവേദക സംഘങ്ങൾക്ക് ഞാൻ അനുവദിച്ചു നൽകിയിരുന്നത് നിങ്ങളും അനുവദിച്ചു നൽകുക." അദ്ദേഹം പറയുന്നു: മൂന്നാമത്തേത് അവിടന്ന് പറഞ്ഞില്ല. അല്ലങ്കിൽ അവിടന്നത് പറഞ്ഞു, പക്ഷേ, ഞാനതു മറന്നുപോയി. (മു)', 'سَعِيدِ بْنِ جُبَيْرٍ', 'സഈദുബ്നു ജൂബൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 686, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرِضْتُ عَامَ الْفَتْحِ مَرَضًا أَشْفَيْتُ مِنْهُ عَلَى الْمَوْتِ، فَأَتَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ لِي مَالًا كَثِيرًا، وَلَيْسَ يَرِثُنِي إِلَّا ابْنَتِي، أَفَأُوصِي بِمَالِي كُلِّهِ؟ قَالَ: "لَا". قُلْتُ: فَثُلُثَيْ مَالِي؟ قَالَ: "لَا". قُلْتُ: فَالشَّطْرُ؟ قَالَ: "لَا". قُلْتُ: فَالثُّلُثُ؟ قَالَ: "الثُّلُثُ، وَالثُّلُثُ كَثِيرٌ، إِنَّكَ إِنْ تَدَعْ وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ مِنْ أَنْ تَدَعَهُمْ عَالَةً يَتَكَفَّفُونَ النَّاسَ، وَإِنَّكَ لَنْ تُنْفِقَ نَفَقَةً إِلَّا أُجِرْتَ فِيهَا، حَتَّى اللُّقْمَةَ تَرْفَعُهَا إِلَى فِي امْرَأَتِكَ". قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أُخَلَّفُ عَنْ هِجْرَتِي؟ قَالَ: "إِنَّكَ لَنْ تُخَلَّفَ بَعْدِي، فَتَعْمَلَ عَمَلًا تُرِيدُ بِهِ وَجْهَ اللَّهِ إِلَّا ازْدَدْتَ بِهِ رِفْعَةً وَدَرَجَةً، وَلَعَلَّكَ أَنْ تُخَلَّفَ حَتَّى يَنْتَفِعَ بِكَ أَقْوَامٌ وَيُضَرَّ بِكَ آخَرُونَ. اللَّهُمَّ أَمْضِ لِأَصْحَابِي هِجْرَتَهُمْ وَلَا تَرُدَّهُمْ عَلَى أَعْقَابِهِمْ، وَلَكِنِ الْبَائِسُ سَعْدُ بْنُ خَوْلَةَ". يَرْثِي لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ مَاتَ بِمَكَّةَ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): മരണത്തോടടുത്ത ഒരു രോഗം മക്കാവിജയ വർഷം എനിക്ക് പിടിപെട്ടു. അപ്പോൾ എന്നെ സന്ദർശിക്കുന്നതിനായി റസൂൽ(സ) എന്റെയടുത്ത് വന്നു. ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം എനിക്ക് ധാരാളം മുതലുണ്ട്. എന്റെ മകൾ മത്രമാണ് എന്നെ അനന്തരമെടുക്കാനുള്ളത്. അതിനാൽ എന്റെ സമ്പത്ത് മുഴുവൻ ഞാൻ വസ്വിയ്യത്ത് ചെയ്യട്ടെയോ? നബി(സ) പറഞ്ഞു: "വേണ്ട." ഞാൻ ചോദിച്ചു: എന്നാൽ മുതലിന്റെ മൂന്നിൽ രണ്ടുഭാഗം? നബി(സ) പറഞ്ഞു: "വേണ്ട." ഞാൻ ചോദിച്ചു: എന്നാൽ പകുതി? നബി(സ) പറഞ്ഞു: "വേണ്ട." ഞാൻ പറഞ്ഞു: എന്നാൽ മൂന്നിലൊന്ന്? നബി(സ) പറഞ്ഞു: "മൂന്നിലൊന്ന് (പറ്റും), മൂന്നിലൊന്ന് തന്നെ ധാരാളമാണ്. നിശ്ചയം നിന്റെ അനന്തരാവകാശികളെ, ജനങ്ങളോട് കൈനീട്ടുന്ന ദരിദ്രരാക്കി വിട്ടേച്ച് പോകുന്നതിനേക്കാൾ അവരെ ധനികരാക്കി വിടുന്നതാണ് ഏറ്റവും പുണ്യമുള്ളത്. നീ ചെലവഴിക്കുന്ന ഓരോ കാര്യത്തിലും നിനക്ക് പ്രതിഫലം നൽകപ്പെടുന്നതാണ്, നിന്റെ ഭാര്യയുടെ വായിലേക്ക് നീ വെച്ചുകൊടുക്കുന്ന ഉരുളക്കുപോലും." നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ ഹിജ്റയെത്തൊട്ട് ഞാൻ പിന്തിക്കപ്പെടുമോ (ഞാൻ ഹിജ്റ നഷ്ടപ്പെട്ടവനാകുമോ)? നബി(സ) പറഞ്ഞു: "നിശ്ചയം എനിക്കുശേഷം (മക്കയിൽ) നീ പിന്തിക്കപ്പെടുകയും അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിച്ചുകൊണ്ട് നീ ഒരു പ്രവർത്തനം പ്രവർത്തിക്കുകയും ചെയ്യുന്നുവെങ്കിൽ അതു കാരണത്താൽ നിന്റെ സ്ഥാനവും ഉന്നതിയും വർദ്ധിക്കുക തന്നെ ചെയ്യും. നീ (ഹിജ്റയിൽ നിന്ന്) പിന്തുകയും അങ്ങനെ നീ കാരണത്താൽ കുറേ ആളുകൾക്ക് ഉപകാരമുണ്ടാവുകയും മറ്റുചിലർക്ക് ബുദ്ധിമുട്ടുണ്ടാവുകയും ചെയ്തേക്കാം. അല്ലാഹുവേ, എന്റെ അനുചരർക്ക് അവരുടെ ഹിജ്റ നീ നടപ്പിലാക്കിക്കൊടുക്കണേ, അവരെ നീ തിരിച്ചയക്കരുതേ. എന്നാൽ, സഅ്ദുബ്നു ഖൗലയാണ് (ഹിജ്റ പോകാൻ കഴിയാതെ) ബുദ്ധിമുട്ടുണ്ടായവൻ." അദ്ദേഹം മക്കയിൽ വെച്ച് മരിച്ചതിന്റെ പേരിൽ നബി(സ) ദുഃഖം പ്രകടിപ്പിക്കുകയായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 687, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرِضْتُ مَرَضًا أَشْفَيْتُ مِنْهُ، فَأَتَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُنِي، فَقُلْتُ: يَا رَسُولَ اللهِ، إِنَّ لِي مَالًا كَثِيرًا، وَلَيْسَ يَرِثُنِي إِلَّا ابْنَتِي، أَفَأَتَصَدَّقُ بِثُلُثَيْ مَالِي؟ – فِي رِوَايَةٍ: بِمَالِي كُلِّهِ؟ – قَالَ: "لَا". قُلْتُ: فَالشَّطْرُ؟ قَالَ: "لَا". قُلْتُ: فَالثُّلُثُ؟ قَالَ: "الثُّلُثَ، وَالثُّلُثُ كَثِيرٌ، إِنَّكَ أَنْ تَتْرُكَ – تَدَعَ – وَرَثَتَكَ أَغْنِيَاءَ خَيْرٌ لَهُمْ مِنْ أَنْ تَتْرُكَهُمْ – تَدَعَهُمْ – عَالَةً يَتَكَفَّفُونَ النَّاسَ – فِي رِوَايَةٍ: مَا فِي أَيْدِيهِمْ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=20), 1, 'وَفِي رِوَايَةٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعُودُهُ وَهُوَ بِمَكَّةَ، وَهُوَ يَكْرَهُ أَنْ يَمُوتَ بِالْأَرْضِ الَّذِي هَاجَرَ مِنْهَا، قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "رَحِمَ اللهُ سَعْدَ بْنَ عَفْرَاءَ: أَوْ يَرْحَمُ اللهُ سَعْدَ بْنَ عَفْرَاءَ". وَلَمْ يَكُنْ لَهُ إِلَّا ابْنَةٌ وَاحِدَةٌ، قَالَ: يَا رَسُولَ اللهِ، أُوصِي بِمَالِي كُلِّهِ؟ ... إِلَى آخِرِ الْحَدِيثِ.', 'മറ്റൊരു നിവേദനം: എന്റെ മതൽ മുഴുവനും (ഞാൻ ദാനം ചെയ്യട്ടെയോ)? - റസൂൽ(സ) പറഞ്ഞു: "വേണ്ട." ഞാൻ ചോദിച്ചു: എന്നാൽ പകുതി? റസൂൽ(സ) പറഞ്ഞു: "വേണ്ട." ഞാൻ ചോദിച്ചു: എന്നാൽ മൂന്നിലൊന്ന്? റസൂൽ(സ) പറഞ്ഞു: "മൂന്നിലൊന്ന് (പറ്റും), മൂന്നിലൊന്ന് തന്നെ ധാരാളമാണ്. നിശ്ചയം നീ നിന്റെ അനന്തരാവകാശികളെ ധനികരാക്കി വിടുന്നതാണ്, ജനങ്ങളോട് -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=20), 2, 'وَفِي رِوَايَةٍ: أَنَّهُ اشْتَكَى بِمَكَّةَ، فَجَاءَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَآهُ سَعْدٌ بَكَى وَقَالَ: يَا رَسُولَ اللهِ، أَمُوتُ بِالْأَرْضِ الَّتِي هَاجَرْتُ مِنْهَا؟ قَالَ: "لَا، إِنْ شَاءَ اللهُ". وَقَالَ: يَا رَسُولَ اللهِ، أُوصِي بِمَالِي كُلِّهِ فِي سَبِيلِ اللهِ... إِلَى آخِرِ الْحَدِيثِ.', 'മറ്റൊരു നിവേദനം: അവരുടെ കയ്യിലുള്ളത് - യാചിക്കുന്ന ദരിദ്രരാക്കി അവരെ വിട്ടേക്കുന്നതിനേക്കാൾ അവർക്ക് ഉത്തമം."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=20), 3, 'وَفِي رِوَايَةٍ: قَالَ: عَادَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِي، فَقَالَ: "أَوْصَيْتَ". قُلْتُ: نَعَمْ، قَالَ: "بِكَمْ". قُلْتُ: بِمَالِي كُلِّهِ فِي سَبِيلِ اللهِ. قَالَ: "فَمَا تَرَكْتَ لِوَلَدِكَ". قُلْتُ: هُمْ أَغْنِيَاءُ. قَالَ: "أَوْصِ بِالْعُشْرِ". فَمَا زَالَ يَقُولُ وَأَقُولُ حَتَّى قَالَ: "أَوْصِ بِالثُّلُثِ، وَالثُّلُثُ كَثِيرٌ". أَوْ: كَبِيرٌ". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: മക്കയിലായിരിക്കെ നബി(സ) അദ്ദേഹത്തെ സന്ദർശിക്കാറുണ്ടായിരുന്നു. താൻ ഹിജ്റ പോയ നാട്ടിൽ വെച്ചുതന്നെ മരിക്കുന്നത് അദ്ദേഹത്തിന് വെറുപ്പായിരുന്നു. നബി(സ) പറഞ്ഞു: "സഅ്ദുബ്നു അഫ്റാഇനെ അല്ലാഹു അനുഗ്രഹിക്കട്ടെ. അല്ലെങ്കിൽ: സഅ്ദുബ്നു അഫ്റാഇനെ അല്ലാഹു അനുഗ്രഹിക്കും." ഒരു മകളല്ലാതെ മറ്റാരും അദ്ദേഹത്തിനുണ്ടായിരുന്നില്ല. അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ മുതൽ മുഴുവൻ ഞാൻ വസ്വിയ്യത്ത് ചെയ്യട്ടെയോ?..... അങ്ങനെ ആ ഹദീസിന്റെ അവസാനം വരെ.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=20), 4, null, 'മറ്റൊരു നിവേദനം: അദ്ദേഹം മക്കയിൽ വെച്ച് രോഗബാധിതനായി. അങ്ങനെ റസൂൽ(സ) അദ്ദേഹത്തിന്റെ അടുത്ത് വന്നു. തിരുമേനി(സ)യെ കണ്ടപ്പോൾ സഅ്ദ്(റ) കരഞ്ഞു, അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ ഹിജ്റ പോയ ഭൂമിയിൽ വെച്ചുതന്നെ ഞാൻ മരിക്കുകയോ? റസൂൽ(സ) പറഞ്ഞു: "ഇല്ല, അല്ലാഹു ഉദ്ദേശിച്ചാൽ." അദ്ദേഹം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ മുഴുവൻ മുതലും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ഞാൻ ചെലവഴിക്കട്ടെയോ?..... അങ്ങനെ ആ ഹദീസിന്റെ അവസാനം വരെ.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=20), 5, null, 'മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: എന്റെ രോഗാവസ്ഥയിൽ റസൂൽ(സ) എന്നെ സന്ദർശിച്ചു. അവിടന്ന് ചോദിച്ചു: "നീ വസ്വിയ്യത്ത് ചെയ്തുവോ?" ഞാൻ പറഞ്ഞു: അതെ. അവിടന്ന് ചോദിച്ചു: "എത്രയുണ്ട്?" ഞാൻ പറഞ്ഞു: എന്റെ മുതൽ മുഴുവൻ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലേക്ക് (വസ്വിയ്യത്ത് ചെയ്തു). അവിടന്ന് ചോദിച്ചു: "അപ്പോൾ നിന്റെ സന്താനങ്ങൾക്ക് എന്താണ് നീ ഒഴിച്ചിട്ടത്?" ഞാൻ പറഞ്ഞു: അവർ ധനികരാണ്. അവിടന്ന് പറഞ്ഞു: "പത്തിലൊന്നുകൊണ്ട് നീ വസ്വിയ്യത്ത് ചെയ്യൂ." അങ്ങനെ ഞാനും തിരുമേനി(സ)യും പരസ്പരം പറഞ്ഞുകൊണ്ടേയിരുന്നു. അവസാനം അവിടന്ന് പറഞ്ഞു: "മൂന്നിലൊന്ന് നീ വസ്വിയ്യത്ത് ചെയ്യൂ, മൂന്നിലൊന്ന് തന്നെ ധാരാളമാണ്. അല്ലെങ്കിൽ: വലുതാണ്." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: وَدِدْتُ أَنَّ النَّاسَ غَضُّوا مِنَ الثُّلُثِ إِلَى الرُّبُعِ، لِأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الثُّلُثُ كَبِيرٌ. أَوْ كَثِيرٌ". (ق,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ജനങ്ങൾ മൂന്നിലൊന്നിൽ നിന്ന് നാലിലൊന്നിലേക്ക് (വസ്വിയ്യത്ത് ചെയ്യുന്ന തോത്) ചുരുക്കണമെന്ന് ഞാൻ കൊതിച്ചുപോയി. കാരണം റസൂൽ(സ) പറഞ്ഞു: "മൂന്നിലൊന്ന് തന്നെ വലിയതാണ്, അല്ലെങ്കിൽ അധികമാണ്." (ബു,മു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 689, 689, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ تَصَدَّقَ عَلَيْكُمْ، عِنْدَ وَفَاتِكُمْ، بِثُلُثِ أَمْوَالِكُمْ، زِيَادَةً لَكُمْ فِي أَعْمَالِكُمْ". [ز: فِي إِسْنَادِهِ ضَعِيفٌ] (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം, നിങ്ങളുടെ പ്രവർത്തനങ്ങളുടെ ആധിക്യത്തിനുവേണ്ടി, അല്ലാഹു നിങ്ങളുടെ സ്വത്തിന്റെ മൂന്നിലൊന്ന്, നിങ്ങളുടെ മരണ സമയത്ത് സ്വദഖ ചെയ്യാവുന്നതാക്കിത്തന്നിരിക്കുന്നു." ഇതിന്റെ പരമ്പരയിൽ ഒരു ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ ضَعِيفٌ', null, 689, 689, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا ابْنَ آدَمَ، اثْنَتَانِ لَمْ تَكُنْ لَكَ وَاحِدَةٌ مِنْهُمَا: جَعَلْتُ لَكَ نَصِيبًا مِنْ مَالِكَ حِينَ أَخَذْتُ بِكَظَمِكَ، لِأُطَهِّرَكَ بِهِ وَأُزَكِّيَكَ. وَصَلَاةُ عِبَادِي عَلَيْكَ بَعْدَ انْقِضَاءِ أَجَلِكَ". [ز: فِي إِسْنَادِهِ رَاوٍ مُخْتَلَفٌ فِيهِ] (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആദം സന്തതിയേ, നിനക്ക് അവകാശമുണ്ടായിരുന്നില്ലാത്ത രണ്ട് കാര്യങ്ങളുണ്ട് (നിനക്ക് ഞാൻ നൽകിയിട്ടുണ്ട്). നിന്റെ തൊണ്ട ഞാൻ പിടിച്ച സമയത്ത്, നിന്നെ ശുദ്ധമാക്കാനും സംസ്കരിക്കാനും വേണ്ടി, നിന്റെ സ്വത്തിലെ ഒരു വിഹിതം ഞാൻ നിനക്കു നൽകി. നിന്റെ ആയുസ്സ് തീർന്ന ശേഷം നിനക്കുമേൽ എന്റെ അടിമകളുടെ നിസ്കാരവും (നിനക്ക് ഞാൻ നൽകി)." ഈ ഹദീസിന്റെ പരമ്പരയിൽ അഭിപ്രായഭിന്നതയുള്ള ഒരു നിവേദകൻ ഉണ്ട്. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ رَاوٍ مُخْتَلَفٌ فِيهِ', null, 689, 689, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، نَبِّئْنِي مَا حَقُّ النَّاسِ مِنِّي بِحُسْنِ الصُّحْبَةِ؟ فَقَالَ: "نَعَمْ، وَأَبِيكَ لَتُنَبَّأَنَّ: أُمُّكَ". قَالَ: ثُمَّ مَنْ؟ قَالَ: "ثُمَّ أُمُّكَ". قَالَ: ثُمَّ مَنْ؟ قَالَ: "ثُمَّ أُمُّكَ". قَالَ: ثُمَّ مَنْ؟ قَالَ: "ثُمَّ أَبُوكَ". قَالَ: نَبِّئْنِي يَا رَسُولَ اللَّهِ عَنْ مَالِي، كَيْفَ أَتَصَدَّقُ فِيهِ؟ قَالَ: "نَعَمْ، وَاللَّهِ لَتُنَبَّأَنَّ، أَنْ تَصَدَّقَ وَأَنْتَ صَحِيحٌ شَحِيحٌ، تَأْمُلُ الْعَيْشَ وَتَخَافُ الْفَقْرَ. وَلَا تُمْهِلْ، حَتَّى إِذَا بَلَغَتْ نَفْسُكَ هَا هُنَا قُلْتَ: مَالِي لِفُلَانٍ وَمَالِي لِفُلَانٍ، وَهُوَ لَهُمْ وَإِنْ كَرِهْتَ". (ق,جه)', 'അബൂഹുറൈറ(റ): ഒരാൾ നബി(സ)യുടെ അടുക്കൽ വന്ന് പറഞ്ഞു: അല്ലഹുവിന്റെ റസൂലേ, നല്ല സഹവാസത്താൽ ജനങ്ങളിൽ എന്നോട് ഏറ്റവും ബന്ധപ്പെട്ടവൻ ആരാണെന്ന് പറഞ്ഞുതന്നാലും? നബി(സ) പറഞ്ഞു: "അതെ, നിന്റെ പിതാവ് തന്നെയാണ് സത്യം, നിന്നോട് അത് അറിയിക്കപ്പെടുക തന്നെ ചെയ്യും, അത് നിന്റെ ഉമ്മയാണ്." അദ്ദേഹം ചോദിച്ചു: പിന്നെ ആരാണ്? നബി(സ) പറഞ്ഞു: "പിന്നെയും നിന്റെ ഉമ്മയാണ്." അദ്ദേഹം ചോദിച്ചു: പിന്നെ ആരാണ്? നബി(സ) പറഞ്ഞു: "പിന്നെയും നിന്റെ ഉമ്മയാണ്." അയാൾ ചോദിച്ചു: പിന്നെ ആരാണ്? നബി(സ) പറഞ്ഞു: "പിന്നീട് നിന്റെ പിതാവാണ്." അയാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ സമ്പത്തിനെക്കുറിച്ച് എനിക്ക് പറഞ്ഞുതന്നാലും, ഞാൻ എങ്ങനെയാണതിൽ ദാനം ചെയ്യുക? നബി(സ) പറഞ്ഞു: "അതെ, അല്ലാഹുവാണ് സത്യം, നിന്നോട് അത് അറിയിക്കപ്പെടുക തന്നെ ചെയ്യും. നീ ജീവിതത്തെ കൊതിക്കുകയും ദാരിദ്ര്യത്തെ ഭയപ്പെടുകയും ആരാഗ്യവാനും അത്യാർത്ഥിയുള്ളവനും ആയിരിക്കുകയും ചെയ്യുന്ന അവസ്ഥയിൽ ദാനം ചെയ്യലാണ് (ഉത്തമം). നിന്റെ ആത്മാവ് ഇവിടെ (തൊണ്ടക്കുഴി) എത്തുംവരെ നീ അതിനെ പിന്തിപ്പിക്കരുത്; അന്നേരം നീ പറയും: എന്റെ മുതൽ ഇന്നവന്നുള്ളതാണ്, എന്റെ മുതൽ ഇന്നവന്നുള്ളതാണ്. നീ ഇഷ്ടപ്പെട്ടിട്ടില്ലെങ്കിലും അത് അവർക്കുള്ളത് തന്നെയാണ്." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 689, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ بُسْرِ بْنِ جَحَّاشٍ الْقُرَشِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَزَقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي كَفِّهِ، ثُمَّ وَضَعَ أُصْبُعَهُ السَّبَّابَةَ وَقَالَ: "يَقُولُ اللَّهُ عَزَّ وَجَلَّ: أَنَّى تُعْجِزُنِي ابْنَ آدَمَ! وَقَدْ خَلَقْتُكَ مِنْ مِثْلِ هَذِهِ. فَإِذَا بَلَغَتْ نَفْسُكَ هَذِهِ – وَأَشَارَ إِلَى حَلْقِهِ – قُلْتَ: أَتَصَدَّقُ. وَأَنَّى أَوَانُ الصَّدَقَةِ". (جه)', 'ബുസ്റുബ്നു ജഹ്ഹാശുൽ ഖുറശി(റ): നബി(സ) അവിടുത്തെ തൃക്കരത്തിൽ തുപ്പി, പിന്നീട് അവിടത്തെ ചൂണ്ടുവിരൽ വെച്ച് പറഞ്ഞു: "അത്യുന്നതനായ അല്ലാഹു പറയുന്നു: ആദം സന്തതിയേ, എങ്ങനെയാണ് നീ എന്നെ പരാചയപ്പെടുത്തുന്നത്? ഇതുപോലുള്ള ഒന്നിൽനിന്നാണ് ഞാൻ നിന്നെ സൃഷ്ടിച്ചിരിക്കുന്നത്. എന്നാൽ നിന്റെ ആത്മാവ് ഇവിടേക്ക് - അവിടന്ന് തൊണ്ടയിലേക്ക് ചൂണ്ടിക്കാട്ടി - എത്തിയാൽ നീ പറയും: ഞാൻ ദാനം ചെയ്യാം. എന്നാൽ ദാനം ചെയ്യാൻ സമയമെവിടെ?" (ജ)', 'بُسْرِ بْنِ جَحَّاشٍ الْقُرَشِيِّ', 'ബുസ്റുബ്നു ജഹ്ഹാശുൽ ഖുറശി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 690, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَأَنْ يَتَصَدَّقَ الْمَرْءُ فِي حَيَاتِهِ بِدِرْهَمٍ خَيْرٌ لَهُ مِنْ أَنْ يَتَصَدَّقَ بِمِائَةِ دِرْهَمٍ عِنْدَ مَوْتِهِ". (د)', 'അബൂസഈദുൽ ഖുദ്രി(റ): റസൂൽ(സ) പറഞ്ഞു: "ജീവിത കാലത്ത് ഒരാൾ ഒരു ദിർഹം ദാനം ചെയ്യുന്നതാണ് തന്റെ മരണ സമയത്ത് നൂറ് ദിർഹം ദാനം ചെയ്യുന്നതിനേക്കാൾ ഉത്തമം." (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 690, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي حُبَيْبَةَ الطَّائِيِّ قَالَ: أَوْصَى إِلَيَّ أَخِي بِطَائِفَةٍ مِنْ مَالِهِ، فَلَقِيتُ أَبَا الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ فَقُلْتُ: إِنَّ أَخِي أَوْصَى إِلَيَّ بِطَائِفَةٍ مِنْ مَالِهِ، فَأَيْنَ تَرَى لِي وَضْعَهُ: فِي الْفُقَرَاءِ، أَوِ الْمَسَاكِينِ، أَوِ الْمُجَاهِدِينَ فِي سَبِيلِ اللَّهِ؟ فَقَالَ: أَمَّا أَنَا فَلَوْ كُنْتُ لَمْ أَعْدِلْ بِالْمُجَاهِدِينَ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَثَلُ الَّذِي يَعْتِقُ عِنْدَ الْمَوْتِ كَمَثَلِ الَّذِي يُهْدِي إِذَا شَبِعَ". حَسَنٌ صَحِيحٌ. (د,ت,ن)', 'അബൂഹുബൈബതുത്ത്വാഈ(റ): എന്റെ സഹോദരൻ തന്റെ സ്വത്തിന്റെ ഒരു ഭാഗം എനിക്കായി വസ്വിയ്യത്ത് ചെയ്തു. അങ്ങനെ ഞാൻ അബുദ്ദർദാഅ്(റ)വിനെ കണ്ടുമുട്ടി. ഞാൻ പറഞ്ഞു: എന്റെ സഹോദരൻ തന്റെ സ്വത്തിന്റെ ഒരു ഭാഗം എനിക്ക് വസ്വിയ്യത്ത് ചെയ്തിരിക്കുന്നു. ഞാനത് എങ്ങനെ വിനിയോഗിക്കണമെന്നാണ് താങ്കളുടെ അഭിപ്രായം: ദരിദ്രർക്കാണോ, പാവങ്ങൾക്കാണോ, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുന്നവർക്കാണോ ചെലവഴിക്കേണ്ടത്? അദ്ദേഹം പറഞ്ഞു: പോരാളികളോട് സമമായി ആരെയും ഞാൻ കാണുന്നില്ലങ്കിലും റസൂൽ(സ) ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "മരണസമയത്ത് അടിമമോചനം നടത്തുന്നവൻ വയർ നിറഞ്ഞശേഷം ദാനം ചെയ്യുന്നവനെപ്പോലെയാണ്." (ദ,തു,ന)', 'أَبِي حُبَيْبَةَ الطَّائِيِّ قَالَ', 'അബൂഹുബൈബതുത്ത്വാഈ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 690, 691, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ فَرَّ مِنْ مِيرَاثِ وَارِثِهِ قَطَعَ اللَّهُ مِيرَاثَهُ مِنَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ". [ز: فِي إِسْنَادِهِ زَيْدُ بْنُ الْحَوَارِي الْعَمِيِّ، وَهُوَ مُخْتَلَفٌ فِيهِ] (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ അനന്തരാവകാശിക്കുള്ള അനന്തരസ്വത്തിൽ നിന്ന് ഒളിച്ചോടിയാൽ (അവർക്ക് അത് ലഭിക്കാതിരിക്കാനുള്ള മാർഗ്ഗം സ്വീകരിച്ചാൽ) അന്ത്യനാളിൽ അല്ലാഹു സ്വർഗ്ഗത്തിൽ നിന്നുള്ള അവന്റെ അനന്തരാവകാശം തടഞ്ഞുവെക്കുന്നതാണ്." ഈ ഹദീസിന്റെ സനദിൽ സൈദുബ്നുൽ ഹവാരിയ്യുൽ അമ്മീ എന്നയാളുണ്ട്. അദ്ദഹത്തിന്റെ കാര്യത്തിൽ അഭിപ്രായ ഭിന്നതയുണ്ട്. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ زَيْدُ بْنُ الْحَوَارِي الْعَمِيِّ، وَهُوَ مُخْتَلَفٌ فِيهِ', null, 691, 691, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الرَّجُلَ لَيَعْمَلُ – وَالْمَرْأَةُ – بِطَاعَةِ اللَّهِ سِتِّينَ سَنَةً، ثُمَّ يَحْضُرُهُمَا الْمَوْتُ، فَيُضَارَّانِ فِي الْوَصِيَّةِ، فَتَجِبُ لَهُمَا النَّارُ". ثُمَّ قَرَأَ عَلَيَّ أَبُو هُرَيْرَةَ: {مِنْ بَعْدِ وَصِيَّةٍ يُوصَى بِهَا أَوْ دَيْنٍ غَيْرَ مُضَارٍّ وَصِيَّةً مِنَ اللَّهِ} إِلَى قَوْلِهِ {ذَلِكَ الْفَوْزُ الْعَظِيمُ}. حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം ഒരാൾ - ഒരു സ്ത്രീയും - അറുപത് വർഷം അല്ലാഹുവിനെ അനുസരിച്ചുകൊണ്ടുള്ള കർമ്മം ചെയ്യും. ശേഷം അവർക്ക് രണ്ടുപേർക്കും മരണമാസന്നമാകുകയും ഇരുവരും വസ്വിയ്യത്തിൽ ബുദ്ധിമുട്ടുണ്ടാക്കുകയും ചെയ്യും. അങ്ങനെ രണ്ടുപേർക്കും നരകം നിർബന്ധമാകും." ശേഷം അബൂഹുറൈറ(റ) എനിക്ക് ഇപ്രകാരം ഓതിത്തന്നു: ''ദ്രോഹകരമല്ലാത്ത വസ്വിയ്യത്തോ കടമോ ഉണ്ടെങ്കിൽ അതിനു ശേഷമാണിത്. അല്ലാഹുവിങ്കൽ നിന്നുള്ള നിർദേശമാണിത്.'' എന്നതുമുതൽ ''അതാണ് മഹത്തായ വിജയം'' എന്നതുവരെ. (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 691, 691, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْخَيْرِ سَبْعِينَ سَنَةً، فَإِذَا أَوْصَى حَافَ فِي وَصِيَّتِهِ، فَيُخْتَمُ لَهُ بِشَرِّ عَمَلِهِ، فَيَدْخُلُ النَّارَ. وَإِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الشَّرِّ سَبْعِينَ سَنَةً، فَيَعْدِلُ فِي وَصِيَّتِهِ، فَيُخْتَمُ لَهُ بِخَيْرِ عَمَلِهِ، فَيَدْخُلُ الْجَنَّةَ". قَالَ أَبُو هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: وَاقْرَءُوا إِنْ شِئْتُمْ: {تِلْكَ حُدُودُ اللَّهِ} إِلَى قَوْلِهِ {عَذَابٌ مُهِينٌ}. (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും, ഒരാൾ എഴുപത് വർഷം സജ്ജനങ്ങളുടെ പ്രവർത്തനം പ്രവർത്തിക്കുകയും ശേഷം വസ്വിയ്യത്ത് ചെയ്യുമ്പോൾ തെറ്റായ മാർഗ്ഗം അവലംബിക്കുകയും ചെയ്യും. അങ്ങനെ തന്റെ ആ തിന്മയുമായി അവന് സീല് വെക്കപ്പെടുകയും അവൻ നരകത്തിൽ പ്രവേശിക്കുകയും ചെയ്യും. തീർച്ചയായും ഒരാൾ എഴുപത് വർഷം ദുഷ്ട ജനങ്ങളുടെ പ്രവർത്തനം പ്രവർത്തിക്കുകയും ശേഷം തന്റെ വസ്വിയ്യത്തിൽ നീതി പുലർത്തുകയും ചെയ്യും. അങ്ങനെ തന്റെ ആ നന്മയുമായി അവന് സീല് വെക്കപ്പെടുകയും അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയും ചെയ്യും." അബുഹുറൈറ(റ) പറയുന്നു: നിങ്ങൾക്ക് വേണമെങ്കിൽ നിങ്ങൾ ഓതുക: ''അത് അല്ലാഹുവിന്റെ അതിരുകളാണ്.'' എന്നതുമുതൽ ''നിന്ദ്യമായ ശിക്ഷയുണ്ട്'' എന്നതുവരെ. (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 691, 691, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ قُرَّةَ بْنِ إِيَاسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ حَضَرَتْهُ الْوَفَاةُ فَأَوْصَى، وَكَانَتْ وَصِيَّتُهُ عَلَى كِتَابِ اللَّهِ، كَانَتْ كَفَّارَةً لِمَا تَرَكَ مِنْ زَكَاتِهِ فِي حَيَاتِهِ". [ز: فِي إِسْنَادِهِ مُدَلِّسٌ عَنْعَنَهُ وَمَجْهُولٌ] (جه)', 'ഖുർറതുബ്നു ഇയാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും മരണമാസന്നമാകുകയും, അവൻ വസ്വിയ്യത്ത് ചെയ്യുകയും, അവന്റെ വസ്വിയ്യത്ത് അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിനനുസൃതമാവുകയും ചെയ്താൽ, അവൻ തന്റെ ജീവിതകാലത്ത് ഒഴിവാക്കിയ തന്റെ സകാതിന് അത് പരിഹാരമാകുന്നതാണ്." ഇതിന്റെ പരമ്പരയിൽ ഒരു മജ്ഹൂലും അൻഅനാക്കിപ്പറഞ്ഞ ഒരു മുദല്ലിസുമുണ്ട്. (ജ)', 'قُرَّةَ بْنِ إِيَاسٍ', 'ഖുർറതുബ്നു ഇയാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: فِي إِسْنَادِهِ مُدَلِّسٌ عَنْعَنَهُ وَمَجْهُولٌ', null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا ذَرٍّ، إِنِّي أَرَاكَ ضَعِيفًا، وَإِنِّي أُحِبُّ لَكَ مَا أُحِبُّ لِنَفْسِي، فَلَا تَأَمَّرَنَّ عَلَى اثْنَيْنِ، وَلَا تَوَلَّيَنَّ مَالَ يَتِيمٍ". (م,د,ن)', 'അബൂദർറ്(റ): എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "അബൂദർറേ, നിശ്ചയം ഞാൻ താങ്കളെ ബലഹീനനായാണ് കാണുന്നത്. ഞാൻ എനിക്ക് ഇഷ്ടപ്പെടുന്നത് താങ്കൾക്ക് ഇഷ്ടപ്പെടുകയും ചെയ്യുന്നു. അതിനാൽ താങ്കൾ രണ്ടാൾക്ക് നേതാവാകുകയോ യതീമിന്റെ മുതലിന്റെ കൈകാര്യകർതൃത്വം ഏറ്റെടുക്കുകയോ ചെയ്യരുത്." (മു,ദ,ന)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: {إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ} [الْبَقَرَة: ١٨٠] فَكَانَتِ الْوَصِيَّةُ كَذَلِكَ حَتَّى نَسَخَتْهَا آيَةُ الْمِيرَاثِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''അവൻ ധനം വിട്ടേച്ചുപോവുകയാണെങ്കിൽ മാതാപിതാക്കൾക്കും അടുത്ത കുടുംബങ്ങൾക്കും വസ്വിയ്യത്ത് ചെയ്യണം.'' (അൽബഖറ: 180) ശേഷം വസ്വിയ്യത്ത് അപ്രകാരം തന്നെയായിരുന്നു. അനന്തരസ്വത്തിന്റെ സൂക്തം അതിനെ ദുർബ്ബലപ്പെടുത്തുന്നത് വരെ. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الْبَقَرَة: ١٨٠', null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي خُطْبَتِهِ عَامَ حَجَّةِ الْوَدَاعِ: "إِنَّ اللَّهَ قَدْ أَعْطَى لِكُلِّ ذِي حَقٍّ حَقَّهُ، فَلَا وَصِيَّةَ لِوَارِثٍ. الْوَلَدُ لِلْفِرَاشِ وَلِلْعَاهِرِ الْحَجَرُ، وَحِسَابُهُمْ عَلَى اللَّهِ. وَمَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ، أَوِ انْتَمَى إِلَى غَيْرِ مَوَالِيهِ، فَعَلَيْهِ لَعْنَةُ اللَّهِ التَّابِعَةُ إِلَى يَوْمِ الْقِيَامَةِ. لَا تُنْفِقُ امْرَأَةٌ مِنْ بَيْتِ زَوْجِهَا إِلَّا بِإِذْنِ زَوْجِهَا". قِيلَ: يَا رَسُولَ اللَّهِ، وَلَا الطَّعَامَ؟ قَالَ: "ذَلِكَ أَفْضَلُ أَمْوَالِنَا". ثُمَّ قَالَ: "الْعَارِيَةُ مُؤَدَّاةٌ، وَالْمِنْحَةُ مَرْدُودَةٌ، وَالدَّيْنُ مَقْضِيٌّ، وَالزَّعِيمُ غَارِمٌ". حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'അബൂഉമാമതുൽ ബാഹിലി(റ): വിടവാങ്ങൽ ഹജ്ജിന്റെ വർഷം തന്റെ പ്രസംഗത്തിൽ റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം അല്ലാഹു ഓരോ അവകാശിക്കും അവന്റെ അവകാശം നൽകിയിരിക്കുന്നു. അതിനാൽ അനന്തരാവകാശിക്ക് വസ്വിയ്യത്ത് ചെയ്യരുത്. സന്താനം വിരിപ്പിന്റെ അവകാശിക്കുള്ളതാണ്. വ്യഭിചാരിക്ക് കല്ലാണുള്ളത്. അവരുടെ വിചാരണ അല്ലാഹുവിങ്കലാണ്. തന്റെ പിതാവല്ലാത്തവനിലേക്ക് ആരെങ്കിലും സ്വന്തത്തെ ചേർത്തിപ്പറഞ്ഞാൽ, അല്ലെങ്കിൽ തന്റെ യജമാനനല്ലാത്തവരെക്കുറിച്ച് അവരാണ് തന്നെ മോചിപ്പിച്ചവരെന്ന് പറഞ്ഞാൽ അവന്റെ മേൽ അന്ത്യനാൾവരെ തുടരുന്ന അല്ലാഹുവിന്റെ ശാപമുണ്ടാവട്ടെ. തന്റെ ഭർത്താവിന്റെ സമ്മതമില്ലാതെ അവന്റെ വീട്ടിൽനിന്നും ഭാര്യ ചെലവഴിക്കരുത്." റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, ഭക്ഷണവും കൊടുക്കാൻ പറ്റില്ലേ? അവിടന്ന് പറഞ്ഞു: "നമ്മുടെ സ്വത്തുകളിൽ ഏറ്റവും ശ്രേഷ്ഠമായത് അതാണ്." പിന്നീട് അവിടന്ന് പറഞ്ഞു: "വായ്പ കൊടുത്തുവീട്ടേണ്ടതാണ്, ഔദാര്യം മടക്കപ്പെടേണ്ടതാണ്, കടം വീട്ടപ്പെടേണ്ടതാണ്, ജാമ്യക്കാരൻ കടക്കാരനാണ്." (ദ,തു,ജ)', 'أَبِي أُمَامَةَ الْبَاهِلِيِّ', 'അബൂഉമാമതുൽ ബാഹിലി(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 692, 693, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَمْرِو بْنِ خَارِجَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَ عَلَى نَاقَتِهِ وَأَنَا تَحْتَ جِرَانِهَا، وَهِيَ تَقْصَعُ بِجِرَّتِهَا، وَإِنَّ لُعَابَهَا يَسِيلُ بَيْنَ كَتِفَيَّ، فَسَمِعْتُهُ يَقُولُ: "إِنَّ اللَّهَ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ، وَلَا وَصِيَّةَ لِوَارِثٍ. وَالْوَلَدُ لِلْفِرَاشِ، وَلِلْعَاهِرِ الْحَجَرُ. وَمَنِ ادَّعَى إِلَى غَيْرِ أَبِيهِ، أَوِ انْتَمَى إِلَى غَيْرِ مَوَالِيهِ رَغْبَةً عَنْهُمْ، فَعَلَيْهِ لَعْنَةُ اللَّهِ، لَا يَقْبَلُ اللَّهُ مِنْهُ صَرْفًا وَلَا عَدْلًا". حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'അംറുബ്നു ഖാരിജ(റ): തന്റെ ഒട്ടകപ്പുറത്തുവെച്ച് നബി(സ) പ്രസംഗിച്ചു. അതിന്റെ മേൽക്കഴുത്തിന് കീഴിലായി ഞാനുമുണ്ട്. അത് അയവിറക്കാനായി തികട്ടിയെടുത്തത് ചവച്ചിറക്കുകയായിരുന്നു. അതിന്റെ ഉമനീർ എന്റെ ഇരു ചുമലുകൾക്കുമിടയിലൂടെ ഒലിക്കുന്നുണ്ടായിരുന്നു. അന്നേരം നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം അല്ലാഹു ഓരോ അവകാശിക്കും അവന്റെ അവകാശം നൽകിയിരിക്കുന്നു. അതിനാൽ അനന്തരാവകാശിക്ക് വസ്വിയ്യത്ത് ചെയ്യരുത്. സന്താനം വിരിപ്പിന്റെ അവകാശിക്കുള്ളതാണ്. വ്യഭിചാരിക്ക് കല്ലാണുള്ളത്. തന്റെ പിതാവല്ലാത്തവനിലേക്ക് ആരെങ്കിലും സ്വന്തത്തെ ചേർത്തിപ്പറഞ്ഞാൽ, അല്ലെങ്കിൽ തന്റെ യജമാനന്മാരെ വെറുത്തത് കാരണത്താൽ അവരല്ലാത്തവരെക്കുറിച്ച് അവരാണ് തന്നെ മോചിപ്പിച്ചവരെന്ന് പറഞ്ഞാൽ അവന്റെ മേൽ അല്ലാഹുവിന്റെ ശാപമുണ്ടായിരിക്കുന്നതാണ്. നിർബന്ധമോ സുന്നത്തോ ആയ ഒരു കർമ്മവും അവനിൽ നിന്ന് അല്ലാഹു സ്വീകരിക്കുകയില്ല." (തു,ന,ജ)', 'عَمْرِو بْنِ خَارِجَةَ', 'അംറുബ്നു ഖാരിജ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 693, 693, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ {وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ} [الشُّعَرَاء: ٢١٤] دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُرَيْشًا فَاجْتَمَعُوا، فَعَمَّ وَخَصَّ، فَقَالَ: "يَا بَنِي كَعْبِ بْنِ لُؤَيٍّ، يَا بَنِي مُرَّةَ بْنِ كَعْبٍ، يَا بَنِي عَبْدِ شَمْسٍ، وَيَا بَنِي عَبْدِ مَنَافٍ، وَيَا بَنِي هَاشِمٍ، وَيَا بَنِي عَبْدِ الْمُطَّلِبِ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ، وَيَا فَاطِمَةُ أَنْقِذِي نَفْسَكِ مِنَ النَّارِ، إِنِّي لَا أَمْلِكُ لَكُمْ مِنَ اللَّهِ شَيْئًا، غَيْرَ أَنَّ لَكُمْ رَحِمًا سَأَبُلُّهَا بِبِلَالِهَا". وَفِي رِوَايَةٍ: "يَا بَنِي عَبْدِ مَنَافٍ، اشْتَرُوا أَنْفُسَكُمْ مِنْ رَبِّكُمْ، إِنِّي لَا أَمْلِكُ لَكُمْ مِنَ اللهِ شَيْئًا. يَا بَنِي عَبْدِ الْمُطَّلِبِ، اشْتَرُوا أَنْفُسَكُمْ مِنْ رَبِّكُمْ، إِنِّي لَا أَمْلِكُ لَكُمْ مِنَ اللهِ شَيْئًا، وَلَكِنْ بَيْنِي وَ بَيْنَكُمْ رَحِمٌ، أَنَا بَالُّهَا بِبَلَالِهَا". (ن)', 'അബൂഹുറൈറ(റ): ''അങ്ങയുടെ ഏറ്റവും അടുത്ത കടുംബങ്ങൾക്ക് അങ്ങ് മുന്നറിയിപ്പ് നൽകുക'' (ശുഅറാഅ്: 214) എന്ന സൂക്തം അവതീർണ്ണമായപ്പോൾ റസൂൽ(സ) ഖുറൈശികളെ വിളിച്ചു. അങ്ങനെ അവർ ഒത്തുകൂടി. അവിടന്ന് അവരെ പൊതുവായും പ്രത്യേകമായും അഭിസംബോധനം ചെയ്തു. അവിടന്ന് പറഞ്ഞു: "കഅ്ബുബ്നു ലുഅയ്യിന്റെ സന്തതികളേ, മുർറതുബ്നു കഅ്ബിന്റെ സന്തതികളേ, അബ്ദുശ്ശംസിന്റെ സന്തതികളേ, അബ്ദുമനാഫിന്റെ സന്തതികളേ, ഹാശിമിന്റെ സന്തതികളേ, അബ്ദുൽ മുത്ത്വലിബിന്റെ സന്തതികളേ, നിങ്ങളുടെ ശരീരങ്ങളെ നരകത്തിൽ നിന്നും നിങ്ങൾ രക്ഷിക്കുക. ഓ ഫാത്വിമ, നിന്റെ ശരീരത്തെ നരകത്തിൽ നിന്നും നീ രക്ഷിക്കുക. നിശ്ചയം അല്ലാഹുവിങ്കൽ നിങ്ങൾക്കായി ഒന്നും തന്നെ ഞാൻ കൈവശപ്പെടുത്തുന്നില്ല. എന്നാൽ നിങ്ങൾക്ക് (ഞാനുമായി) കുടുംബബന്ധമുണ്ട്, അതിനുവേണ്ട നനവ് ഞാൻ അതിന് നൽകും (ഐഹിക ലോകത്ത് അതിന്റെ അവകാശങ്ങൾ വകവെച്ചു തരും)." മറ്റൊരു നിവേദനം: "അബ്ദുമനാഫിന്റെ സന്തതികളേ, നിങ്ങളുടെ രക്ഷിതാവിൽ നിന്നും നിങ്ങളുടെ ശരീരങ്ങളെ നിങ്ങൾ വാങ്ങുക, നിശ്ചയം അല്ലാഹുവിങ്കൽ നിങ്ങൾക്കായി ഒന്നും തന്നെ ഞാൻ കൈവശപ്പെടുത്തുന്നില്ല. അബ്ദുൽമുത്ത്വലിബിന്റെ സന്തതികളേ, നിങ്ങളുടെ രക്ഷിതാവിൽ നിന്നും നിങ്ങളുടെ ശരീരങ്ങളെ നിങ്ങൾ വാങ്ങുക, നിശ്ചയം അല്ലാഹുവിങ്കൽ നിങ്ങൾക്കായി ഒന്നും തന്നെ ഞാൻ കൈവശപ്പെടുത്തുന്നില്ല. എന്നാൽ എനിക്കും നിങ്ങൾക്കുമിടയിൽ കുടുംബബന്ധമുണ്ട്. അതുമായി ബന്ധപ്പെട്ട അവകാശങ്ങൾ ഞാൻ വകവെച്ചു നൽകുന്നതായിരിക്കും." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], 'الشُّعَرَاء: ٢١٤', null, 693, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=36), 1, 'وَفِي رِوَايَةٍ: "يَا بَنِي عَبْدِ مَنَافٍ، اشْتَرُوا أَنْفُسَكُمْ مِنْ رَبِّكُمْ، إِنِّي لَا أَمْلِكُ لَكُمْ مِنَ اللهِ شَيْئًا. يَا بَنِي عَبْدِ الْمُطَّلِبِ، اشْتَرُوا أَنْفُسَكُمْ مِنْ رَبِّكُمْ، إِنِّي لَا أَمْلِكُ لَكُمْ مِنَ اللهِ شَيْئًا، وَلَكِنْ بَيْنِي وَ بَيْنَكُمْ رَحِمٌ، أَنَا بَالُّهَا بِبَلَالِهَا". (ن)', 'മറ്റൊരു നിവേദനം: "അബ്ദുമനാഫിന്റെ സന്തതികളേ, നിങ്ങളുടെ രക്ഷിതാവിൽ നിന്നും നിങ്ങളുടെ ശരീരങ്ങളെ നിങ്ങൾ വാങ്ങുക, നിശ്ചയം അല്ലാഹുവിങ്കൽ നിങ്ങൾക്കായി ഒന്നും തന്നെ ഞാൻ കൈവശപ്പെടുത്തുന്നില്ല. അബ്ദുൽമുത്ത്വലിബിന്റെ സന്തതികളേ, നിങ്ങളുടെ രക്ഷിതാവിൽ നിന്നും നിങ്ങളുടെ ശരീരങ്ങളെ നിങ്ങൾ വാങ്ങുക, നിശ്ചയം അല്ലാഹുവിങ്കൽ നിങ്ങൾക്കായി ഒന്നും തന്നെ ഞാൻ കൈവശപ്പെടുത്തുന്നില്ല. എന്നാൽ എനിക്കും നിങ്ങൾക്കുമിടയിൽ കുടുംബബന്ധമുണ്ട്. അതുമായി ബന്ധപ്പെട്ട അവകാശങ്ങൾ ഞാൻ വകവെച്ചു നൽകുന്നതായിരിക്കും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ {وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ} قَالَ: "يَا مَعْشَرَ قُرَيْشٍ [أَوْ كَلِمَةً نَحْوَهَا] اشْتَرُوا أَنْفُسَكُمْ لَا أُغْنِي عَنْكُمْ مِنَ اللَّهِ شَيْئًا، يَا بَنِي عَبْدِ مَنَافٍ لَا أُغْنِي عَنْكُمْ مِنَ اللَّهِ شَيْئًا، يَا عَبَّاسُ بْنَ عَبْدِالْمُطَّلِبِ لَا أُغْنِي عَنْكَ مِنَ اللَّهِ شَيْئًا، وَيَا صَفِيَّةُ عَمَّةَ رَسُولِ اللَّهِ لَا أُغْنِي عَنْكِ مِنَ اللَّهِ شَيْئًا، وَيَا فَاطِمَةُ بِنْتَ مُحَمَّدٍ سَلِينِي مَا شِئْتِ مِنْ مَالِي لَا أُغْنِي عَنْكِ مِنَ اللهِ شَيْئًا". (خ)', 'അബൂഹുറൈറ(റ): ''അങ്ങയുടെ ഏറ്റവും അടുത്ത കടുംബങ്ങൾക്ക് അങ്ങ് മുന്നറിയിപ്പ് നൽകുക'' എന്ന സൂക്തം അല്ലാഹു ഇറക്കിയപ്പോൾ റസൂൽ(സ) എഴുന്നേറ്റ് നിന്നുകൊണ്ട് പറഞ്ഞു: "ഓ ഖുറൈശീ സമൂഹമേ, (അല്ലെങ്കിൽ അതുപോലോത്ത എന്തോ വാക്ക് പറഞ്ഞു) നിങ്ങളുടെ ശരീരങ്ങളെ നിങ്ങൾ വാങ്ങുക, അല്ലാഹുവിങ്കൽ നിങ്ങൾക്കായി ഒന്നും തന്നെ ഞാൻ ഉടമപ്പെടുത്തുന്നില്ല. അബുദുമനാഫിന്റെ സന്തതികളേ, അല്ലാഹുവിങ്കൽ നിങ്ങൾക്കായി ഒന്നും തന്നെ ഞാൻ ഉടമപ്പെടുത്തുന്നില്ല. അബ്ബാസുബ്നു അബ്ദിൽ മുത്ത്വലിബേ, അല്ലാഹുവിങ്കൽ താങ്കൾക്കായി ഒന്നും തന്നെ ഞാൻ ഉടമപ്പെടുത്തുന്നില്ല. അല്ലാഹുവിന്റെ റസൂലിന്റെ പിതൃസഹോദരിയായ സ്വഫിയ്യാ, അല്ലാഹുവിങ്കൽ നിങ്ങൾക്കായി ഒന്നും തന്നെ ഞാൻ ഉടമപ്പെടുത്തുന്നില്ല. മുഹമ്മദിന്റെ മകളായ ഫാത്വിമാ, എന്റെ മുതലിൽ നിന്ന് ഇഷ്ടമുള്ളയത്ര നിനക്കെന്നോട് ചോദിക്കാം, എന്നാൽ അല്ലാഹുവിങ്കൽ നിനക്കായി ഒന്നും തന്നെ ഞാൻ ഉടമപ്പെടുത്തുന്നില്ല." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], 'أَوْ كَلِمَةً نَحْوَهَا', null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ أَبَاهُ تُوُفِّيَ وَعَلَيْهِ دَيْنٌ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ أَبِي تُوُفِّيَ وَعَلَيْهِ دَيْنٌ، وَلَمْ يَتْرُكْ إِلَّا مَا يُخْرِجُ نَخْلُهُ، وَلَا يَبْلُغُ مَا يُخْرِجُ نَخْلُهُ مَا عَلَيْهِ مِنَ الدَّيْنِ دُونَ سِنِينَ، فَانْطَلِقْ مَعِي يَا رَسُولَ اللَّهِ، لِكَيْ لَا يُفْحِشَ عَلَيَّ الْغُرَّامُ. فَأَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدُورُ بَيْدَرًا بَيْدَرًا، فَسَلَّمَ حَوْلَهُ وَدَعَا لَهُ، ثُمَّ جَلَسَ عَلَيْهِ، وَدَعَا الْغُرَّامَ فَأَوْفَاهُمْ، وَبَقِيَ مِثْلُ مَا أَخَذُوا. (ن)', 'ജാബിർ(റ): അദ്ദഹത്തിന്റെ പിതാവ് കടബാധ്യതയുള്ളവനായിരിക്കെ മരണപ്പെട്ടു. (അദ്ദേഹം പറയുന്നു:) അപ്പോൾ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, കടബാധ്യതയുണ്ടായിരിക്കെയാണ് എന്റെ പിതാവ് മരണപ്പെട്ടത്. അദ്ദേഹത്തിന്റെ ഈത്തപ്പനത്തോട്ടം നൽകുന്ന വരുമാനമല്ലാതെ മറ്റൊന്നും അദ്ദേഹം അവശേഷിപ്പിച്ചിട്ടില്ല. കുറേ വർഷങ്ങൾ കൊണ്ടല്ലാതെ അദ്ദേഹത്തിന്റെ ഈത്തപ്പനത്തോട്ടത്തിൽ നിന്നുള്ള വരുമാനം അദ്ദേഹത്തിന്റെ കടത്തിന് തികയുകയില്ല. അല്ലാഹുവിന്റെ റസൂലേ, അതിനാൽ കടക്കാർ എന്നോട് മോശത്തരമൊന്നും കാണിക്കാതിരിക്കാൻ അവിടന്ന് എന്റെകൂടെ വന്നാലും. അങ്ങനെ തിരുമേനി(സ) ഓരോരോ കാരക്കക്കൂമ്പാരങ്ങൾ ചുറ്റിനടന്നു. അവിടന്ന് അതിനുചുറ്റും സലാം പറഞ്ഞ് അതിനുവേണ്ടി പ്രാർത്ഥിച്ചു. ശേഷം അതിനുമേൽ ഇരുന്നു. പീന്നീട് കടക്കാരെ വിളിച്ച് അവർക്കുവേണ്ടതു അവിടന്ന് നൽകി. എന്നാൽ അവരെടുത്ത അത്രതന്നെ അവശേഷിക്കുകയും ചെയ്തു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 694, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: تُوُفِّيَ عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ حَرَامٍ، قَالَ: وَتَرَكَ دَيْنًا، فَاسْتَشْفَعْتُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى غُرَمَائِهِ أَنْ يَضَعُوا مِنْ دَيْنِهِ شَيْئًا، فَطَلَبَ إِلَيْهِمْ فَأَبَوْا، فَقَالَ لِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اذْهَبْ فَصَنِّفْ تَمْرَكَ أَصْنَافًا: الْعَجْوَةَ عَلَى حِدَةٍ، وَعِذْقَ ابْنِ زَيْدٍ عَلَى حِدَةٍ، وَأَصْنَافَهُ، ثُمَّ ابْعَثْ إِلَيَّ". قَالَ: فَفَعَلْتُ، فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَلَسَ فِي أَعْلَاهُ، أَوْ فِي أَوْسَطِهِ، ثُمَّ قَالَ: "كِلْ لِلْقَوْمِ". قَالَ: فَكِلْتُ لَهُمْ حَتَّى أَوْفَيْتُهُمْ، ثُمَّ بَقِيَ تَمْرِي كَأَنْ لَمْ يَنْقُصْ مِنْهُ شَيْءٌ. (ن)', 'ജാബിർ(റ): അബ്ദുല്ലാഹിബ്നു അംറുബ്നു ഹിറാം(റ) വഫാതായി. നിവേദകൻ പറയുന്നു: അദ്ദേഹം കുറേ കടം ബാക്കിവെച്ചിരുന്നു. അങ്ങനെ അയാളുടെ കടത്തിൽ നിന്നും വല്ലതും കടക്കാർ കുറച്ചുനൽകുന്നതിനുവേണ്ടി ശിപാർശ ചെയ്യാൻ ഞാൻ റസൂൽ(സ)യോട് ആവശ്യപ്പെട്ടു. അവിടന്ന് അവരോടത് ആവശ്യപ്പെട്ടെങ്കിലും അവരത് നിരസിച്ചു. അപ്പോൾ റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നീ പോയി നിന്റെ കാരക്ക തരംതിരിച്ച് വെക്കുക: അജ്വ ഒരു ഭാഗത്ത്, ഇദ്ഖുബ്നിസൈദ് (ഒരിനം കാരക്ക) ഒരു ഭാഗത്ത്, അങ്ങനെ ഓരോ ഇനവും. ശേഷം നീ എന്റെ അടുത്തേക്ക് ആളെ അയക്കുക." അദ്ദേഹം പറയുന്നു: ഞാനപ്രകാരം ചെയ്തു. അപ്പോൾ റസൂൽ(സ) വന്ന് അതിന്റെ മുകളിൽ, അല്ലെങ്കിൽ: അതിന്റെ നടുവിൽ ഇരിക്കുകയും ചെയ്തു. ശേഷം പറഞ്ഞു: "നീ ജനങ്ങൾക്ക് അളന്നുനൽകുക." അദ്ദേഹം പറയുന്നു: അപ്പോൾ ഞാൻ അവർക്ക് മുഴുവൻ അളന്നു നൽകി. എന്നിട്ടും ഒന്നുംകുറഞ്ഞിട്ടില്ലാത്ത പോലെ എന്റെ കാരക്ക ബാക്കിയായി. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 695, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ أَخْبَرَهُ أَنَّ أَبَاهُ تُوُفِّيَ وَتَرَكَ عَلَيْهِ ثَلَاثِينَ وَسْقًا لِرَجُلٍ مِنْ يَهُودَ، فَاسْتَنْظَرَهُ جَابِرٌ فَأَبَى، فَكَلَّمَ جَابِرٌ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَشْفَعَ لَهُ إِلَيْهِ، فَجَاءَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَكَلَّمَ الْيَهُودِيَّ لِيَأْخُذَ ثَمَرَ نَخْلِهِ بِالَّذِي لَهُ عَلَيْهِ، فَأَبَى عَلَيْهِ، وَكَلَّمَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُنْظِرَهُ فَأَبَى... وَسَاقَ الْحَدِيثَ. (خ,د,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഒരു യഹൂദിക്ക് നൽകാനുള്ള മുപ്പത് വസ്ഖ് (കാരക്ക) കടം തനിക്കുമേൽ ഉപേക്ഷിച്ചുകൊണ്ടാണ് അദ്ദേഹത്തിന്റെ പിതാവ് മരണപ്പെട്ടത്. ജാബിർ(റ) ആ യഹൂദിയോട് അവധി നീട്ടിത്തരാൻ ആവശ്യപ്പെട്ടെങ്കിലും അയാളത് നിരസിച്ചു. അപ്പോൾ തനിക്കുവേണ്ടി യഹൂദിയോട് ശിപാർശ ചെയ്യാൻ അദ്ദേഹം നബി(സ)യോട് ആവശ്യപ്പെട്ടു. അങ്ങനെ റസൂൽ(സ) വരികയും അദ്ദേഹത്തിന്റെ കടത്തിനുപകരം ഈത്തപ്പനയിലെ കായ്കൾ എടുക്കുന്ന വിഷയത്തെക്കുറിച്ച് സംസാരിക്കുകയും ചെയ്തു. എന്നാൽ യഹൂദി അത് നിരസിച്ചു. അദ്ദേഹത്തിന് അവധി നീട്ടിക്കൊടുക്കുന്നതിന് വേണ്ടിയും റസൂൽ(സ) സംസാരിച്ചു. അതും യഹൂദി നിരസിച്ചു.... ശേഷം അദ്ദേഹം ആ ഹദീസ് തുടർന്നു. (ബു,ദ,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 695, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ لِيَهُودِيٍّ عَلَى أَبِي تَمْرٌ، فَقُتِلَ يَوْمَ أُحُدٍ، وَتَرَكَ حَدِيقَتَيْنِ، وَتَمْرُ الْيَهُودِيِّ يَسْتَوْعِبُ مَا فِي الْحَدِيقَتَيْنِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ لَكَ أَنْ تَأْخُذَ الْعَامَ نِصْفَهُ وَتُؤَخِّرَ نِصْفَهُ". فَأَبَى الْيَهُودِيُّ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ لَكَ أَنْ تَأْخُذَ الْجِدَادَ؟ فَآذِنِّي". فَآذَنْتُهُ فَجَاءَ هُوَ وَأَبُو بَكْرٍ، فَجَعَلَ يُجَدُّ وَيُكَالُ مِنْ أَسْفَلِ النَّخْلِ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْعُو بِالْبَرَكَةِ، حَتَّى وَفَيْنَاهُ جَمِيعَ حَقِّهِ مِنْ أَصْغَرِ الْحَدِيقَتَيْنِ، ثُمَّ أَتَيْتُهُمْ بِرُطَبٍ وَمَاءٍ، فَأَكَلُوا وَشَرِبُوا، ثُمَّ قَالَ: "هَذَا مِنَ النَّعِيمِ الَّذِي تُسْأَلُونَ عَنْهُ". (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഒരു ജൂതന് എന്റെ പിതാവ് കുറേ കാരക്ക നൽകാനുണ്ടായിരുന്നു. അങ്ങനെ അദ്ദേഹം ഉഹ്ദ് ദിവസം വധിക്കപ്പെട്ടു. അദ്ദേഹം രണ്ട് തോട്ടങ്ങൾ ഉപേക്ഷിച്ചിട്ടിരുന്നു. എന്നാൽ യഹൂദിക്ക് നൽകാനുള്ള കാരക്ക രണ്ട് തോട്ടങ്ങളിലുള്ള ഫലങ്ങൾ കൊണ്ടും തികയാത്തതായിരുന്നു. അപ്പോൾ നബി(സ) (യഹൂദിയോട്) ചോദിച്ചു: "ഈ വർഷം അതിന്റെ പകുതിയെടുത്ത് പകുതിക്കുള്ള അവധി നീട്ടിത്തരാൻ നീ തയ്യാറുണ്ടോ?" എന്നാൽ യഹൂദി അത് സമ്മതിച്ചില്ല. അപ്പോൾ അവിടന്ന് (എന്നോട്) പറഞ്ഞു: "നിനക്ക് വിളവെടുപ്പിന് സമയമായില്ലേ? ആയാൽ എന്നെ വിവരം അറിയിക്കണം." ശേഷം ഞാൻ തിരുമേനി(സ)യെ വിവരമറിയിക്കുകയും തിരുമേനി(സ)യും അബൂബക്കർ(റ)വും വരികയും ചെയ്തു. അങ്ങനെ ഈത്തപ്പഴം പറിക്കപ്പെടുകയും ഈത്തപ്പനയുടെ ചുവട്ടിൽ വെച്ചുതന്നെ അളക്കപ്പെടുകയും ചെയ്യാൻ തുടങ്ങി. റസൂൽ(സ) ബറക്കത്തിന്നായി പ്രാർത്ഥിച്ചുകൊണ്ടിരിക്കുകയായിരുന്നു. അങ്ങനെ ഏറ്റവും ചെറിയ തോട്ടത്തിൽ നിന്നുതന്നെ ആ യഹൂദിക്ക് നൽകാനുള്ളതെല്ലാം ഞങ്ങൾ നൽകി. ശേഷം അവരുടെ അടുത്തേക്ക് ഞാൻ ഈത്തപ്പഴവും വെള്ളവുമായി വന്നു. അവർ അത് ഭക്ഷിക്കുകയും കുടിക്കുകയും ചെയ്തു. ശേഷം തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളോട് ചോദിക്കപ്പെടുന്ന അനുഗ്രഹങ്ങളിൽ പെട്ടതാണിത്." (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 695, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: تُوُفِّيَ أَبِي وَعَلَيْهِ دَيْنٌ، فَعَرَضْتُ عَلَى غُرَمَائِهِ أَنْ يَأْخُذُوا الثَّمَرَةَ بِمَا عَلَيْهِ فَأَبَوْا، وَلَمْ يَرَوْا فِيهِ وَفَاءً، فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهُ، قَالَ: "إِذَا جَدَدْتَهُ فَوَضَعْتَهُ فِي الْمِرْبَدِ فَآذِنِّي". فَلَمَّا جَدَدْتُهُ وَوَضَعْتُهُ فِي الْمِرْبَدِ أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ وَمَعَهُ أَبُو بَكْرٍ وَعُمَرُ، فَجَلَسَ عَلَيْهِ وَدَعَا بِالْبَرَكَةِ، ثُمَّ قَالَ: "ادْعُ غُرَمَاءَكَ فَأَوْفِهِمْ". قَالَ: فَمَا تَرَكْتُ أَحَدًا لَهُ عَلَى أَبِي دَيْنٌ إِلَّا قَضَيْتُهُ، وَفَضَلَ لِي ثَلَاثَةُ عَشَرَ وَسْقًا، فَذَكَرْتُ ذَلِكَ لَهُ فَضَحِكَ، وَقَالَ: "ائْتِ أَبَا بَكْرٍ وَعُمَرَ فَأَخْبِرْهُمَا ذَلِكَ". فَأَتَيْتُ أَبَا بَكْرٍ وَعُمَرَ فَأَخْبَرْتُهُمَا، فَقَالَا: قَدْ عَلِمْنَا إِذْ صَنَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا صَنَعَ أَنَّهُ سَيَكُونُ ذَلِكَ. (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): എന്റെ പിതാവ് കടബാധ്യതയുള്ളവനായിട്ടാണ് മരണപ്പെട്ടത്. അപ്പോൾ ഞാനദ്ദേഹത്തിന്റെ കടക്കാരോട്, അദ്ദേഹം നൽകാനുള്ളതിന് പകരമായി ഫലങ്ങൾ എടുത്തുകൊള്ളാൻ പറഞ്ഞു. എന്നാൽ അവരത് നിരസിച്ചു. കടം വീട്ടാൻ അത് തികയുമെന്ന് അവർക്ക് തോന്നിയില്ല. അപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് അക്കാര്യം അവിടത്തോട് പറഞ്ഞു. അവിടന്ന് പറഞ്ഞു: "നീ ആ കാരക്ക പറിച്ചെടുത്ത് മെതിക്കളത്തിൽ വെക്കുമ്പോൾ എന്നെ അറിയിക്കുക." അങ്ങനെ അത് പറിച്ചെടുത്ത് മെതിക്കളത്തിൽ വെച്ചപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ തിരുമേനി(സ) വന്നു. അവിടത്തോടൊപ്പം അബൂബക്കർ(റ)വും ഉമർ(റ)വും ഉണ്ടായിരുന്നു. അവിടന്ന് അതിനുമേൽ ഇരിക്കുകയും ബറക്കത്തിനായി പ്രാർത്ഥിക്കുകയും ചെയ്തു. ശേഷം പറഞ്ഞു: "നിന്റെ കടക്കാരെ വിളിച്ച് അവർക്ക് പൂർണ്ണമായും (കടം) വീട്ടിക്കൊടുക്കുക." അദ്ദേഹം പറയുന്നു: എന്റെ പിതാവിന് കടബാധ്യതയുണ്ടായിരുന്ന ഒരാളെയും ഞാൻ ഒഴിവാക്കിയില്ല. എന്നാൽ പതിമൂന്ന് വസ്ഖ് (കാരക്ക) എനിക്ക് ബാക്കിയാവുകയും ചെയ്തു. അക്കാര്യം ഞാൻ തിരുമേനി(സ)യോട് പറഞ്ഞപ്പോൾ അവിടന്ന് ചിരിച്ചുകൊണ്ട് പറഞ്ഞു: "നീ അബൂബക്കറിന്റെയും ഉമറിന്റെയും അടുത്ത് ചെന്ന് ഈ വിവരം പറയുക." അങ്ങനെ ഞാൻ അബൂബക്കർ(റ)വിന്റെയും ഉമർ(റ)വിന്റെയും അടുത്ത് ചെന്ന് അക്കാര്യം പറഞ്ഞു. അപ്പോൾ അവർ രണ്ടുപേരും പറഞ്ഞു: റസൂൽ(സ) അപ്രകാരം ചെയ്തപ്പോൾ തന്നെ ഇപ്രകാരം ഉണ്ടാകുമെന്ന് ഞങ്ങൾ മനസ്സിലാക്കിയിരിക്കുന്നു. (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 696, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَاهُ اسْتُشْهِدَ يَوْمَ أُحُدٍ وَتَرَكَ سِتَّ بَنَاتٍ، وَتَرَكَ عَلَيْهِ دَيْنًا، فَلَمَّا حَضَرَ جِدَادُ النَّخْلِ أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: قَدْ عَلِمْتَ أَنَّ وَالِدِي اسْتُشْهِدَ يَوْمَ أُحُدٍ، وَتَرَكَ دَيْنًا كَثِيرًا، وَإِنِّي أُحِبُّ أَنْ يَرَاكَ الْغُرَمَاءُ. قَالَ: "اذْهَبْ فَبَيْدِرْ كُلَّ تَمْرٍ عَلَى نَاحِيَةٍ". فَفَعَلْتُ، ثُمَّ دَعَوْتُهُ، فَلَمَّا نَظَرُوا إِلَيْهِ كَأَنَّمَا أُغْرُوا بِي تِلْكَ السَّاعَةَ، فَلَمَّا رَأَى مَا يَصْنَعُونَ أَطَافَ حَوْلَ أَعْظَمِهَا بَيْدَرًا ثَلَاثَ مَرَّاتٍ، ثُمَّ جَلَسَ عَلَيْهِ، ثُمَّ قَالَ: "ادْعُ أَصْحَابَكَ". فَمَا زَالَ يَكِيلُ لَهُمْ حَتَّى أَدَّى اللَّهُ أَمَانَةَ وَالِدِي، وَأَنَا رَاضٍ أَنْ يُؤَدِّيَ اللَّهُ أَمَانَةَ وَالِدِي، لَمْ تَنْقُصْ تَمْرَةً وَاحِدَةً. (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): അദ്ദേഹത്തിന്റെ പിതാവ് ആറ് പെൺമക്കളെ ഉപേക്ഷിച്ച് ഉഹ്ദിന്റെ ദിവസം രക്തസാക്ഷിയായി. അദ്ദേഹത്തിന് കടവും ഉണ്ടായിരുന്നു. അങ്ങനെ ഈത്തപ്പഴം പറിക്കുന്ന കാലമായപ്പോൾ ഞാൻ റസൂൽ(സ)യുടെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: ധാരാളം കടം ബാക്കിവെച്ച് എന്റെ പിതാവ് ഉഹ്ദിന്റെ ദിവസം രക്തസാക്ഷിയായത് അവിടത്തേക്കറിയാമല്ലോ. കടം കിട്ടാനുള്ളവർ അങ്ങയെ കാണണമെന്നാണ് ഞാൻ ആഗ്രഹിക്കുന്നത്. റസൂൽ(സ) പറഞ്ഞു: "നീ പോയി ഒരോ ഇനം കാരക്കയും ഓരോ ഭാഗത്ത് വെക്കുക." അപ്പോൾ ഞാനപ്രകാരം ചെയ്തു. ശേഷം തിരുമേനി(സ)യെ ക്ഷണിച്ചു. അങ്ങനെ അവർ (കടക്കാർ) തിരുമേനി(സ)യിലേക്ക് നോക്കുമ്പോൾ അവർ എന്നെ ചുറ്റപ്പറ്റിയ മട്ടായിരുന്നു. അവരുടെ പ്രവർത്തനങ്ങൾ കണ്ടപ്പോൾ റസൂൽ(സ) അതിൽ ഏറ്റവും വലിയ കൂമ്പാരത്തിനു ചുറ്റും മൂന്ന് പ്രാവശ്യം ചുറ്റുകയും ശേഷം അതിനുമേലെ ഇരിക്കുകയും ചെയ്തു. ശേഷം പറഞ്ഞു: "നിന്റെ ആളുകളെ വിളിക്കൂ." അങ്ങനെ, ഒരു കാരക്കപോലും കുറയാതെ എന്റെ പിതാവിന്റെ കടം അല്ലാഹു വീട്ടുന്നതുവരെയും, എന്റെ പിതാവിന്റെ കടും അല്ലാഹു വീട്ടുന്നതിൽ ഞാൻ സന്തുഷ്ടനാകുന്നത് വരെയും, അവിടന്ന് അവർക്ക് അളന്നു കൊടുത്തുകൊണ്ടേയിരുന്നു. (ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 696, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَضَى رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالدَّيْنِ قَبْلَ الْوَصِيَّةِ، وَأَنْتُمْ تَقْرَءُونَهَا: {مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ} [النِّساء: ١١]، وَإِنَّ أَعْيَانَ بَنِي الْأُمِّ لَيَتَوَارَثُونَ دُونَ بَنِي الْعَلَّاتِ. (ت,جه)', 'അലി(റ): വസ്വിയ്യത്തിന് മുമ്പ് കടം പരിഗണിക്കപ്പെടണമെന്ന് റസൂൽ(സ) വിധിച്ചു. ''നിങ്ങൾ ചെയ്യുന്ന വസ്വിയ്യത്തിനും കടത്തിനും ശേഷം'' (നിസാഅ്: 11) എന്ന് നിങ്ങൾ പാരായണം ചെയ്യുന്നു. നിശ്ചയം പിതാവും മാതാവുമൊത്ത സഹോദരങ്ങൾ പരസ്പരം അനന്തരമെടുക്കും, എന്നാൽ പിതാവൊത്ത സഹോദരങ്ങൾ അപ്രകാരമല്ല. (തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'النِّساء: ١١', null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالدَّيْنِ قَبْلَ الْوَصِيَّةِ، وَأَنْتُمْ تَقْرَؤُونَ الْوَصِيَّةَ قَبْلَ الدَّيْنِ. (ت,جه)', 'അലി(റ): (വസ്വിയ്യത്തിനെക്കുറിച്ച് പരാമർശിക്കുന്ന സൂക്തം) പാരായണം ചെയ്യുമ്പോൾ നിങ്ങൾ വസ്വിയ്യത്തിനെ കടത്തിനുമുമ്പ് പറയുന്നുവെങ്കിലും വസ്വിയ്യത്തിനു മുമ്പ് കടം പരിഗണിക്കപ്പെടണമെന്ന് നബി(സ) വിധിച്ചിട്ടുണ്ട്. (തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً أَتَتْ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: كُنْتُ تَصَدَّقْتُ عَلَى أُمِّي بِوَلِيدَةٍ، وَإِنَّهَا مَاتَتْ وَتَرَكَتْ تِلْكَ الْوَلِيدَةَ؟ قَالَ: "قَدْ وَجَبَ أَجْرُكِ، وَرَجَعَتْ إِلَيْكِ فِي الْمِيرَاثِ". قَالَتْ: وَإِنَّهَا مَاتَتْ وَعَلَيْهَا صَوْمُ شَهْرٍ، أَفَيُجْزِئُ – أَوْ: يَقْضِي عَنْهَا – أَنْ أَصُومَ عَنْهَا؟ قَالَ: "نَعَمْ". قَالَتْ: وَإِنَّهَا لَمْ تَحُجَّ، أَفَيُجْزِئُ – أَوْ: يَقْضِي عَنْهَا – أَنْ أَحُجَّ عَنْهَا؟ قَالَ: "نَعَمْ". (م,د,ت,جه)', 'ബുറൈദ(റ): ഒരു സ്ത്രീ റസൂൽ(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു. ഞാൻ എന്റെ ഉമ്മാക്ക് ഒരു അടിമസ്ത്രീയെ ദാനമായി നൽകിയിരുന്നു. അവർ മരിക്കുകയും ആ അടിമസ്ത്രീയെ ഉപേക്ഷിച്ചിടുകയും ചെയ്തിരിക്കുന്നു? റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ പ്രതിഫലം സ്ഥിരപ്പെടുകയും ആ അടിമസ്ത്രീ അനന്തരസ്വത്തായി നിന്നിലേക്ക് മടങ്ങുകയും ചെയ്തിരിക്കുന്നു." ആ സ്ത്രീ പറഞ്ഞു: ഒരു മാസത്തെ നോമ്പ് അനുഷ്ഠിക്കാനുണ്ടായിരിക്കെയാണ് അവർ മരിച്ചത്. അവർക്കുവേണ്ടി ഞാനത് നോറ്റുവീട്ടിയാൽ മതിയാകുമോ - അല്ലെങ്കിൽ: അവരുടെ നോമ്പ് വീടുമോ -? റസൂൽ(സ) പറഞ്ഞു: "അതെ." ആ സ്ത്രീ പറഞ്ഞു: അവർ ഹജ്ജ് ചെയ്തിട്ടുണ്ടായിരുന്നില്ല. അതിനാൽ അവർക്കുവേണ്ടി ഞാൻ ഹജ്ജ് ചെയ്താൽ മതിയാകുമോ - അല്ലെങ്കിൽ: അവരുടെ ഹജ്ജ് വീടുമോ -? റസൂൽ(സ) പറഞ്ഞു: "അതെ." (മു,ദ,തു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 697, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةِ أَشْيَاءَ: مِنْ صَدَقَةٍ جَارِيَةٍ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ، أَوْ وَلَدٍ صَالِحٍ يَدْعُو لَهُ". (م,د,ت,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മനുഷ്യൻ മരണപ്പെട്ടാൽ മൂന്ന് കാര്യങ്ങളിൽ നിന്നൊഴികെ അവന്റെ കർമ്മങ്ങൾ മുറിയുന്നതാണ്: സ്ഥിരമായ (മുറിയാതെ പ്രതിഫലം ലഭിക്കുന്ന) ദാനം, ഉപകാരപ്രദമായ വിജ്ഞാനം, തനിക്കുവേണ്ടി പ്രാർത്ഥിക്കുന്ന നല്ല സന്താനം എന്നിവയാണവ." (മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 698, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ الشَّرِيدِ بْنِ سُوَيْدٍ الثَّقَفِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: إِنَّ أُمِّي أَوْصَتْ أَنْ تُعْتَقَ عَنْهَا رَقَبَةٌ، وَإِنَّ عِنْدِي جَارِيَةً نُوبِيَّةً، أَفَيُجْزِئُ عَنِّي أَنْ أُعْتِقَهَا عَنْهَا؟ قَالَ: "ائْتِنِي بِهَا". فَأَتَيْتُهُ بِهَا، فَقَالَ لَهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ رَبُّكِ". قَالَتْ: اللهُ. قَالَ: "مَنْ أَنَا". قَالَتْ: أَنْتَ رَسُولُ اللهِ. قَالَ: "فَأَعْتِقْهَا، فَإِنَّهَا مُؤْمِنَةٌ". (ن)', 'ശരീദുബ്നു സുവൈദുസ്സഖഫി(റ): ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: എന്റെ മാതാവ് അവർക്ക് വേണ്ടി ഒരു അടിമയെ മോചിപ്പിക്കണമെന്ന് വസ്വിയ്യത്ത് ചെയ്തിരുന്നു. എന്റെ പക്കലാണെങ്കിൽ നൂബിയക്കാരിയായ ഒരു അടിമസ്ത്രീയുണ്ട്. അവർക്കു വേണ്ടി അവളെ ഞാൻ മോചിപ്പിച്ചാൽ എന്നിൽ നിന്നത് സ്വീകാര്യമാകുമോ? റസൂൽ(സ) പറഞ്ഞു: "അവളെ എന്റെ അടുത്ത് കൊണ്ടുവരിക." അങ്ങനെ അവളെ ഞാൻ തിരുമേനി(സ)യുടെ അടുത്ത് കൊണ്ടുവന്നു. അവിടന്ന് അവളോട് ചോദിച്ചു: "ആരാണ് നിന്റെ രക്ഷിതാവ്?" അവൾ പറഞ്ഞു: അല്ലാഹു. റസൂൽ(സ) ചോദിച്ചു: "ഞാൻ ആരാണ്?" അവൾ പറഞ്ഞു: അങ്ങ് അല്ലാഹുവിന്റെ റസൂലാണ്. റസൂൽ(സ) പറഞ്ഞു: "അവളെ നീ മോചിപ്പിക്കുക, നശ്ചയം അവൾ സത്യവിശ്വാസിനിയാണ്." (ന)', 'الشَّرِيدِ بْنِ سُوَيْدٍ الثَّقَفِيِّ', 'ശരീദുബ്നു സുവൈദുസ്സഖഫി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 698, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ أُمِّي مَاتَتْ وَعَلَيْهَا نَذْرٌ، أَفَيُجْزِئُ عَنْهَا أَنْ أُعْتِقَ عَنْهَا؟ قَالَ: "أَعْتِقْ عَنْ أُمِّكَ". وَفِي رِوَايَةٍ: أَنَّهُ اسْتَفْتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَذْرٍ كَانَ عَلَى أُمِّهِ، فَتُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْضِهِ عَنْهَا". وَفِي رِوَايَةٍ قَالَ: مَاتَتْ أُمِّي وَعَلَيْهَا نَذْرٌ، فَسَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَنِي أَنْ أَقْضِيَهُ عَنْهَا. (ن)', 'സഅ്ദുബ്നു ഉബാദ(റ)വിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ): അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: എന്റെ മാതാവിന് ഒരു നേർച്ച വീട്ടാനുണ്ടായിരിക്കെ അവർ മരണപ്പെട്ടിരിക്കുന്നു. അതിനാൽ അവർക്കുവേണ്ടി ഞാൻ അടിമയെ മോചിപ്പിക്കുന്നത് അവർക്ക് മതിയാകുമോ? റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ മാതാവിന് പകരം നീ അടിമയെ മോചിപ്പിക്കുക." മറ്റൊരു നിവേദനം: തന്റെ മാതാവ് നേരുകയും അങ്ങനെ വീട്ടാൻ കഴിയാതെ അവർ മരിക്കുകയും ചെയ്ത ഒരു നേർച്ചയെക്കുറിച്ച് അദ്ദേഹം റസൂൽ(സ)യോട് ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവർക്ക് പകരം നീ അത് വീട്ടുക." മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: നേർച്ച വീട്ടാനുണ്ടായിരക്കെയാണ് എന്റെ മാതാവ് മരിച്ചത്. അതേക്കുറിച്ച് ഞാൻ നബി(സ)യോട് ചോദിച്ചു. അവിടന്ന് അവർക്ക് പകരം അത് വീട്ടാൻ എന്നോട് കൽപിച്ചു. (ന)', 'ابْنِ عَبَّاسٍ', 'സഅ്ദുബ്നു ഉബാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 698, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=49), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ اسْتَفْتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَذْرٍ كَانَ عَلَى أُمِّهِ، فَتُوُفِّيَتْ قَبْلَ أَنْ تَقْضِيَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اقْضِهِ عَنْهَا".', 'മറ്റൊരു നിവേദനം: തന്റെ മാതാവ് നേരുകയും അങ്ങനെ വീട്ടാൻ കഴിയാതെ അവർ മരിക്കുകയും ചെയ്ത ഒരു നേർച്ചയെക്കുറിച്ച് അദ്ദേഹം റസൂൽ(സ)യോട് ചോദിച്ചു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അവർക്ക് പകരം നീ അത് വീട്ടുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=49), 2, 'وَفِي رِوَايَةٍ قَالَ: مَاتَتْ أُمِّي وَعَلَيْهَا نَذْرٌ، فَسَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَنِي أَنْ أَقْضِيَهُ عَنْهَا. (ن)', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: നേർച്ച വീട്ടാനുണ്ടായിരക്കെയാണ് എന്റെ മാതാവ് മരിച്ചത്. അതേക്കുറിച്ച് ഞാൻ നബി(സ)യോട് ചോദിച്ചു. അവിടന്ന് അവർക്ക് പകരം അത് വീട്ടാൻ എന്നോട് കൽപിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، إِنَّ أُمِّي مَاتَتْ، أَفَأَتَصَدَّقُ عَنْهَا؟ قَالَ: "نَعَمْ". قُلْتُ: فَأَيُّ الصَّدَقَةِ أَفْضَلُ؟ قَالَ: "سَقْيُ الْمَاءِ". وَفِي رِوَايَةٍ: فَتِلْكَ سِقَايَةُ سَعْدٍ بِالْمَدِينَةِ. (ن)', 'സഅ്ദുബ്നു ഉബാദ(റ): ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം എന്റെ മാതാവ് മരണപ്പെട്ടിരിക്കുന്നു. അതിനാൽ അവർക്കുവേണ്ടി ഞാൻ ദാനം ചെയ്യട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." ഞാൻ ചോദിച്ചു: എങ്കിൽ ഏതു ദാനമാണ് ഉത്തമം? റസൂൽ(സ) പറഞ്ഞു: "വെള്ളം നൽകൽ." മറ്റൊരു നിവേദനം: അതാണ് സഅ്ദ്(റ)വിന്റെ മദീനയിലുള്ള ജലസംഭരണി. (ന)', 'سَعْدِ بْنِ عُبَادَةَ', 'സഅ്ദുബ്നു ഉബാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=50), 1, 'وَفِي رِوَايَةٍ: فَتِلْكَ سِقَايَةُ سَعْدٍ بِالْمَدِينَةِ. (ن)', 'മറ്റൊരു നിവേദനം: അതാണ് സഅ്ദ്(റ)വിന്റെ മദീനയിലുള്ള ജലസംഭരണി. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللهِ، إِنَّ أُمِّي تُوُفِّيَتْ، أَفَيَنْفَعُهَا إِنْ تَصَدَّقْتُ عَنْهَا؟ فَقَالَ: "نَعَمْ". قَالَ: فَإِنَّ لِي مَخْرَفًا، وَإِنِّي أُشْهِدُكَ أَنِّي قَدْ تَصَدَّقْتُ بِهِ عَنْهَا. (خ,د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ മാതാവ് മരണപ്പെട്ടിരിക്കുന്നു, അവർക്കുവേണ്ടി ഞാൻ ദാനം ചെയ്താൽ അവർക്കത് ഉപകാരപ്പെടുമോ? നബി(സ) പറഞ്ഞു: "അതെ." അദ്ദേഹം പറഞ്ഞു: എനിക്കൊരു തോട്ടമുണ്ട്. അത് ഞാൻ അവർക്കുവേണ്ടി ദാനം ചെയ്തിരിക്കുന്നുവെന്ന് ഞാനിതാ അങ്ങയെ സാക്ഷ്യപ്പെടുത്തുന്നു. (ബു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا سَأَلَ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَبِي مَاتَ وَتَرَكَ مَالًا، وَلَمْ يُوصِ، فَهَلْ يُكَفِّرُ عَنْهُ إِنْ تَصَدَّقْتُ عَنْهُ؟ قَالَ: "نَعَمْ". (جه)', 'അബൂഹുറൈറ(റ): ഒരാൾ റസൂൽ(സ)യോട് ഇപ്രകാരം ചോദിച്ചു: നിശ്ചയം എന്റെ പിതാവ് സമ്പത്ത് ഉപേക്ഷിച്ചുകൊണ്ട് മരണപ്പെട്ടിരിക്കുന്നു. എന്നാൽ അദ്ദേഹം വസ്വിയ്യത്ത് ചെയ്തിട്ടില്ല. ഇനി അദ്ദേഹത്തിനു പകരം ഞാൻ ദാനം ചെയ്യുന്നത് അദ്ദേഹത്തിനുള്ള പ്രായശ്ചിത്തമാകുമോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ أُمِّي افْتُلِتَتْ نَفْسُهَا وَلَمْ تُوصِ، وَإِنِّي أَظُنُّهَا لَوْ تَكَلَّمَتْ لَتَصَدَّقَتْ، فَلَهَا أَجْرٌ إِنْ تَصَدَّقْتُ عَنْهَا، وَلِيَ أَجْرٌ؟ فَقَالَ: "نَعَمْ". (م,جه)', 'ആഇശ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: നിശ്ചയം എന്റെ മാതാവ് പെട്ടെന്ന് മരണപ്പെട്ടു. അവരാണെങ്കിൽ വസ്വിയ്യത്ത് ചെയ്തിട്ടുമില്ല. അവർക്ക് സംസാരിക്കാൻ സാധിക്കുകയായിരുന്നെങ്കിൽ അവർ ധാനം ചെയ്യുമായിരുന്നു. അതിനാൽ അവർക്കുവേണ്ടി ഞാൻ ദാനം ചെയ്താൽ അവർക്കും എനിക്കും പ്രതിഫലം ലഭിക്കുമോ? നബി(സ) പറഞ്ഞു: "അതെ." (മു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللهُ عَنْهُ: خَرَجَ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ مَغَازِيهِ، وَحَضَرَتْ أُمَّهُ الْوَفَاةُ بِالْمَدِينَةِ، فَقِيلَ لَهَا: أَوْصِي. فَقَالَتْ: فِيمَ أُوصِي، الْمَالُ مَالُ سَعْدٍ؟ فَتُوُفِّيَتْ قَبْلَ أَنْ يَقْدَمَ سَعْدٌ، فَلَمَّا قَدِمَ سَعْدٌ ذُكِرَ ذَلِكَ لَهُ، فَقَالَ: يَا رَسُولَ اللهِ، هَلْ يَنْفَعُهَا أَنْ أَتَصَدَّقَ عَنْهَا؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ". فَقَالَ سَعْدٌ: حَائِطُ كَذَا وَكَذَا صَدَقَةٌ عَنْهَا. لِحَائِطٍ سَمَّاهُ. (ن)', 'സഅ്ദുബ്നുഉബാദ(റ): അദ്ദേഹം നബി(സ)യോടൊപ്പം ഒരു യുദ്ധത്തിന് പുറപ്പെട്ടു. ആ സമയത്ത് മദീനയിൽ വെച്ച് അദ്ദേഹത്തിന്റെ മാതാവിന് മരണമാസന്നമായി. അപ്പോൾ മഹതിയോട് പറയപ്പട്ടു: നിങ്ങൾ വസ്വിയ്യത്ത് ചെയ്യുക. മഹതി ചോദിച്ചു: എന്തിലാണ് ഞാൻ വസ്വിയ്യത്ത് ചെയ്യുക, ഈ മുതലെല്ലാം സഅ്ദിന്റേതല്ലേ? അങ്ങനെ സഅ്ദ്(റ) തിരിച്ചുവരും മുമ്പ് മഹതി വഫാതായി. സഅ്ദ്(റ) തിരിച്ചെത്തിയപ്പോൾ വിവരങ്ങളെല്ലാം അദ്ദേഹത്തോട് പറയപ്പെട്ടു. അദ്ദേഹം റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവർക്കുവേണ്ടി ഞാൻ ദാനം ചെയ്താൽ അവർക്കത് ഉപകരിക്കുമോ? നബി(സ) പറഞ്ഞു: "അതെ." അപ്പോൾ ഒരു തോട്ടത്തിന്റെ പേരുപറഞ്ഞ് സഅ്ദ്(റ) പറഞ്ഞു: ഇന്നാലിന്ന തോട്ടം അവർക്ക് വേണ്ടിയുള്ള ദാനമാണ്. (ന)', 'سَعْدِ بْنِ عُبَادَةَ', 'സഅ്ദുബ്നുഉബാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 700, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ الْعَاصَ بْنَ وَائِلٍ أَوْصَى أَنْ يُعْتَقَ عَنْهُ مِائَةُ رَقَبَةٍ، فَأَعْتَقَ ابْنُهُ هِشَامٌ خَمْسِينَ رَقَبَةً، فَأَرَادَ ابْنُهُ عَمْرٌو أَنْ يُعْتِقَ عَنْهُ الْخَمْسِينَ الْبَاقِيَةَ، فَقَالَ: حَتَّى أَسْأَلَ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ أَبِي أَوْصَى بِعَتْقِ مِائَةِ رَقَبَةٍ، وَإِنَّ هِشَامًا أَعْتَقَ عَنْهُ خَمْسِينَ، وَبَقِيَتْ عَلَيْهِ خَمْسُونَ رَقَبَةً، أَفَأُعْتِقُ عَنْهُ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ لَوْ كَانَ مُسْلِمًا، فَأَعْتَقْتُمْ عَنْهُ أَوْ تَصَدَّقْتُمْ عَنْهُ أَوْ حَجَجْتُمْ عَنْهُ، بَلَغَهُ ذَلِكَ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): തനിക്കുവേണ്ടി നൂറ് അടിമകളെ മോചിപ്പിക്കണമെന്ന് ആസ്വുബ്നു വാഇൽ വസ്വിയ്യത്ത് ചെയ്തിട്ടുണ്ടായിരുന്നു. അങ്ങനെ അയാളുടെ മകനായ ഹിഷാം അമ്പത് അടിമകളെ മോചിപ്പിച്ചു. ശേഷം അയാളുടെ മകനായ അംറ്(റ) അയാൾക്കുവേണ്ടി ബാക്കിയുള്ള അമ്പത് അടിമകളെക്കൂടി മോചിപ്പിക്കാൻ ആഗ്രഹിച്ചു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ)യോട് ചോദിച്ച ശേഷം മാത്രമേ ഞാനത് ചെയ്യൂ. അങ്ങനെ അദ്ദേഹം നബി(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നൂറ് അടിമകളെ മോചിപ്പിക്കണമെന്ന് എന്റെ പിതാവ് വസ്വിയ്യത്ത് ചെയ്തിട്ടുണ്ടായിരുന്നു. ഹിഷാം അദ്ദേഹത്തിനുവേണ്ടി അമ്പത് അടിമകളെ മോചിപ്പിച്ചിട്ടുണ്ട്. ഇനി അമ്പത് അടിമകളെക്കൂടി മോചിപ്പിക്കാൻ ബാക്കിയുണ്ട്. ഞാൻ അയാൾക്കുവേണ്ടി അവരെ മോചിപ്പിക്കട്ടെയോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം അവൻ മുസ്ലിമായിരുന്നുവെങ്കിൽ, നിങ്ങൾ അവനുവേണ്ടി അടിമകളെ മോചിപ്പിക്കുകയും ദാനം ചെയ്യുകയും ഹജ്ജ് ചെയ്യുകയുമെല്ലാം ചെയ്തിരുന്നുവെങ്കിൽ അവനത് എത്തുമായിരുന്നു."(ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 700, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ بَرِيرَةَ رَضِيَ اللهُ عَنْهَا جَاءَتْ تَسْتَعِينُ عَائِشَةَ فِي كِتَابَتِهَا، وَلَمْ تَكُنْ قَضَتْ مِنْ كِتَابَتِهَا شَيْئًا، فَقَالَتْ لَهَا عَائِشَةُ: ارْجِعِي إِلَى أَهْلِكِ، فَإِنْ أَحَبُّوا أَنْ أَقْضِيَ عَنْكِ كِتَابَتَكِ، وَيَكُونَ لِي وَلَاؤُكِ، فَعَلْتُ. فَذَكَرَتْ ذَلِكَ بَرِيرَةُ لِأَهْلِهَا فَأَبَوْا، وَقَالُوا: إِنْ شَاءَتْ أَنْ تَحْتَسِبَ عَلَيْكِ، وَيَكُونَ لَنَا وَلَاؤُكِ، فَلْتَفْعَلْ. فَذَكَرَتْ ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ابْتَاعِي، فَأَعْتِقِي، فَإِنَّمَا الْوَلَاءُ لِمَنْ أَعْتَقَ". ثُمَّ قَامَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَا بَالُ أَقْوَامٍ يَشْتَرِطُونَ شُرُوطًا لَيْسَتْ فِي كِتَابِ اللهِ؟ مَنِ اشْتَرَطَ شَرْطًا لَيْسَ فِي كِتَابِ اللهِ فَلَيْسَ لَهُ، وَإِنِ اشْتَرَطَ مِائَةَ مَرَّةٍ". حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'ആഇശ(റ): ബരീറ(റ) തന്റെ മോചനപത്രത്തിൽ സഹായം തേടി ആഇശ(റ)യെ സമീപിച്ചു. തന്റെ മോചനപത്രത്തിലെ ഒന്നുംതന്നെ ബരീറ(റ) വീട്ടിയിട്ടുണ്ടായിരുന്നില്ല. ആഇശ(റ) പറഞ്ഞു: നീ നിന്റെ കുടുംബത്തിലേക്ക് മടങ്ങുക. നിന്റെ മോചനപത്രത്തിലെ തുക ഞാൻ വീട്ടുകയും നിന്റെ പിന്തുടർച്ചാവകാശം എനിക്കാവുകയും ചെയ്യുന്നതിനെ അവർ ഇഷ്ടപ്പെടുന്നുണ്ടെങ്കിൽ ഞാനങ്ങനെ ചെയ്യാം. അപ്പോൾ ബരീറ(റ) അക്കാര്യം തന്റെ കുടുംബത്തോട് പറഞ്ഞു. പക്ഷേ, അവരത് നിരസിച്ചു. അവർ പറഞ്ഞു: ആഇശ(റ) നിനക്ക് നന്മ ചെയ്തുതരികയും നിന്റെ പിന്തുടർച്ചാവകാശം ഞങ്ങൾക്കാവുകയും ചെയ്യുകയാണെങ്കിൽ അവർക്ക് അങ്ങനെ ചെയ്യാം. അക്കാര്യം ആഇശ(റ) റസൂൽ(സ)യോട് പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) മഹതിയോട് പറഞ്ഞു: "നീ അവളെ വാങ്ങി മോചിപ്പിക്കുക, നിശ്ചയം പിന്തുടർച്ചാവകാശം മോചിപ്പിച്ചവന്നാണ്." ശേഷം റസൂൽ(സ) എഴുന്നേറ്റ് നിന്നുകൊണ്ട് പറഞ്ഞു: "അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലില്ലാത്ത കുറേ നിബന്ധനകൾ വെക്കുന്ന ആളുകളുടെ അവസ്ഥയെന്താണ്? ആരെങ്കിലും അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലില്ലാത്ത വല്ല നിബന്ധനയും വെച്ചാൽ അവനത് ലഭിക്കുകയില്ല. അവൻ നൂറ് പ്രാവശ്യം നിബന്ധന വെച്ചാലും ശരി." (ബു,മു,ദ,തു,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 700, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَا أَجِدُ شَيْئًا. وَلَيْسَ لِي مَالٌ، وَلِي يَتِيمٌ لَهُ مَالٌ. قَالَ: "كُلْ مِنْ مَالِ يَتِيمِكَ، غَيْرَ مُسْرِفٍ وَلَا مُتَأَثِّلٍ مَالًا". قَالَ: وَأَحْسِبُهُ قَالَ: "وَلَا تَقِي مَالَكَ بِمَالِهِ". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ നബി(സ)യുടെ അടുത്തുവന്ന് പറഞ്ഞു: എനിക്കൊന്നും തന്നെ ഇല്ല, എനിക്ക് സമ്പത്തുമില്ല, എന്നാൽ മുതലുള്ള ഒരു അനാഥൻ എന്റെ കീഴിലുണ്ട്. നബി(സ) പറഞ്ഞു: "ദുർവ്യയം നടത്താതെയും മുതൽ കവർന്നെടുക്കാതെയും നിന്റെ അനാഥന്റെ സ്വത്തിൽ നിന്ന് നീ ചെലവഴിക്കുക." നിവേദകൻ പറയുന്നു: തിരുമേനി(സ) ഇപ്രകാരം പറഞ്ഞുവെന്ന് ഞാൻ വിചാരിക്കുന്നു: "നിന്റെ മുതൽ അവന്റെ മുതലുമായി നീ കൂട്ടിക്കലർത്തരുത്." (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 701, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: فِي قَوْلِهِ: {إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا} قَالَ: كَانَ يَكُونُ فِي حَجْرِ الرَّجُلِ الْيَتِيمُ، فَيَعْزِلُ لَهُ طَعَامَهُ وَشَرَابَهُ وَآنِيَتَهُ، فَشَقَّ ذَلِكَ عَلَى الْمُسْلِمِينَ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {وَإِنْ تُخَالِطُوهُمْ فَإِخْوَانُكُمْ} فِي الدِّينِ، فَأَحَلَّ لَهُمْ خُلْطَتَهُمْ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''അക്രമപരമായി അനാഥരുടെ സമ്പത്ത് ഭക്ഷിക്കുന്നവർ'' എന്ന സൂക്തത്തെക്കുറിച്ച് അദ്ദേഹം പറയുന്നു: ഒരാളുടെ സംരക്ഷണത്തിൽ ഒരു അനാഥനുണ്ടെങ്കിൽ അയാൾ ആ അനാഥന്റെ ഭക്ഷണവും വെള്ളവും പാത്രങ്ങളും ഒഴിവാക്കേണ്ട അവസ്ഥയുണ്ടായി. അത് മുസ്ലിംകൾക്ക് പ്രയാസമായിത്തോന്നി. അപ്പോൾ അല്ലാഹു ഈ സൂക്തമിറക്കി: ''നിങ്ങൾ അവരുമായി ഇടപഴകിക്കഴിയുന്നുവെങ്കിൽ (പ്രശ്നമില്ല). അവർ നിങ്ങളുടെ സഹോദരങ്ങളാണല്ലോ'' അഥവാ ദീനിന്റെ വിഷയത്തിലുള്ള (സഹോദരങ്ങൾ). അങ്ങനെ അവരുമായി ഇടപഴകുന്നതിനെ അല്ലാഹു അവർക്ക് അനുവദനീയമാക്കിക്കൊടുത്തു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 701, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا أَنْزَلَ اللهُ عَزَّ وَجَلَّ: {وَلَا تَقْرَبُوا مَالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ} [الأنعام: ١٥٢]. وَ {إِنَّ الَّذِينَ يَأْكُلُونَ أَمْوَالَ الْيَتَامَى ظُلْمًا} [النّساء: ١٠] الْآيَةَ. انْطَلَقَ مَنْ كَانَ عِنْدَهُ يَتِيمٌ فَعَزَلَ طَعَامَهُ مِنْ طَعَامِهِ، وَشَرَابَهُ مِنْ شَرَابِهِ، فَجَعَلَ يَفْضُلُ مِنْ طَعَامِهِ فَيُحْبَسُ لَهُ حَتَّى يَأْكُلَهُ أَوْ يَفْسُدَ، فَاشْتَدَّ ذَلِكَ عَلَيْهِمْ، فَذَكَرُوا ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {وَيَسْأَلُونَكَ عَنِ الْيَتَامَى قُلْ إِصْلَاحٌ لَهُمْ خَيْرٌ وَإِنْ تُخَالِطُوهُمْ فَإِخْوَانُكُمْ} [البقرة: ٢٢٠] فَخَلَطُوا طَعَامَهُمْ بِطَعَامِهِ وَشَرَابَهُمْ بِشَرَابِهِ. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ''വളരെ നല്ലരീതിയിലല്ലാതെ അനാഥന്റെ മുതലിനെ നിങ്ങൾ സമീപിക്കരുത്.'' (അൻആം: 152), ''അക്രമപരമായി അനാഥരുടെ സമ്പത്ത് ഭക്ഷിക്കുന്നവർ'' (നിസാഅ്: 10) എന്നീ സൂക്തങ്ങൾ അല്ലാഹു അവതരിപ്പിച്ചപ്പോൾ, തങ്ങളുടെ സംരക്ഷണത്തിൽ അനാഥരുള്ള ആളുകളെല്ലാം ചെന്ന് അനാഥന്റെ ഭക്ഷണം തന്റെ ഭക്ഷണത്തിൽ നിന്നും അവന്റെ പാനീയം തന്റെ പാനീയത്തിൽ നിന്നും വേർതിരിച്ചു. ശേഷം അനാഥന്റെ ഭക്ഷണത്തിൽ വല്ലതും അവശേഷിച്ചാൽ, അവനുവേണ്ടിത്തന്നെ അത് സൂക്ഷിച്ച്, അവൻ ഭക്ഷിക്കുകയോ അല്ലെങ്കിൽ ഭക്ഷണം കേടായിപ്പോവുകയോ ചെയ്യുന്ന അവസ്ഥയുണ്ടായി. അത് ജനങ്ങൾക്ക് പ്രയാസകരമായിത്തോന്നി. അങ്ങനെ അക്കാര്യം അവർ റസൂൽ(സ)യോട് പറഞ്ഞു. അപ്പോൾ അല്ലാഹു ഈ സൂക്തമിറക്കി: ''അനാഥരെക്കുറിച്ച് അവർ നിങ്ങളോട് ചോദിക്കുന്നു. നബിയേ, പറയുക: അവർക്ക് നന്മ ചെയ്യലാണ് ഉത്തമം, അവരുമായി നിങ്ങൾ ഇടപഴകിക്കഴിയുന്നുവെങ്കിൽ (കുഴപ്പമില്ല). അവർ നിങ്ങളുടെ സഹോദരങ്ങളാണല്ലോ.'' (അൽബഖറ: 220). അപ്പോൾ ജനങ്ങൾ അനാഥന്റെ ഭക്ഷണം തങ്ങളുടെ ഭക്ഷണവുമായും അവന്റെ പാനീയം തങ്ങളുടെ പാനീയവുമായും കൂട്ടിക്കലർത്തി. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], 'البقرة: ٢٢٠', null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: حَفِظْتُ عَنْ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يُتْمَ بَعْدَ احْتِلَامٍ، وَلَا صُمَاتَ يَوْمٍ إِلَى اللَّيْلِ". (د)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): റസൂൽ(സ)യിൽ നിന്ന് ഞാൻ ഇത് മനഃപ്പാഠമാക്കി: "പ്രായപൂർത്തിയായ ശേഷം അനാഥത്തം ഇല്ല, പകൽ തൊട്ട് രാത്രി വരെ മൗനമവലംബിക്കാൻ പാടില്ല." (ദ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ". قِيلَ: يَا رَسُولَ اللهِ، وَمَا هُنَّ؟ قَالَ: "الشِّرْكُ بِاللهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللهُ إِلَّا بِالْحَقِّ، وَأَكْلُ الرِّبَا، وَأَكْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ". (ق,د,ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "(നന്മകളെ) നശിപ്പിക്കുന്ന എഴ് കാര്യങ്ങളെ നിങ്ങൾ ഉപേക്ഷിക്കുക." അവിടത്തോട് ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, ഏതെല്ലാമാണവ? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിനോട് പങ്കുചേർക്കൽ, മാരണം ചെയ്യൽ, അല്ലാഹു നിഷിദ്ധമാക്കിയ ശരീരത്തെ അവകാശത്തോടുകൂടെയല്ലാതെ വധിക്കൽ, പലിശ ഭക്ഷിക്കൽ, അനാഥന്റെ മുതൽ ഭക്ഷിക്കൽ, യുദ്ധദിവസം പിന്തിരിഞ്ഞോടൽ, സത്യവിശ്വാസിനികളും അശ്രദ്ധരും ചാരിത്രശുദ്ധിയുള്ളവരുമായ സ്ത്രീകൾക്കെതിരെ വ്യഭിചാരാരോപണം നടത്തൽ." (ബു,മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 702, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عُمَيْرِ بْنِ قَتَادَةَ رَضِيَ اللهُ عَنْهُ، وَكَانَتْ لَهُ صُحْبَةٌ: أَنَّ رَجُلًا سَأَلَ فَقَالَ: يَا رَسُولَ اللهِ، مَا الْكَبَائِرُ؟ فَقَالَ: "هُنَّ تِسْعٌ". فَذَكَرَ مَعْنَاهُ زَادَ: "وَعُقُوقُ الْوَالِدَيْنِ الْمُسْلِمَيْنِ، وَاسْتِحْلَالُ الْبَيْتِ الْحَرَامِ، قِبْلَتِكُمْ أَحْيَاءً وَأَمْوَاتًا". (د,ن)', 'ഉമൈറുബ്നു ഖതാദ(റ) - അദ്ദേഹം നബി(സ)യെ സഹവസിച്ചയാളാണ് - ഒരാൾ ഇപ്രകാരം ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, വൻപാപങ്ങൾ ഏതെല്ലാമാണ്? റസൂൽ(സ) പറഞ്ഞു: "അവ ഒൻപതെണ്ണമാണ്." ശേഷം അദ്ദേഹം ആദ്യഹദീസിന്റെ അതേ ആശയം പറഞ്ഞു. അതിൽ ഇതുകൂടിയുണ്ട്: "മുസ്ലിംകളായ മാതാപിതാക്കളെ ധിക്കരിക്കൽ, ജീവിതകാലത്തും മരണശേഷവും നിങ്ങളുടെ ഖിബ്ലയായ പരിശുദ്ധവീട് (കഅ്ബ) അനുവദനീയമാക്കൽ (അവിടെ അക്രമം പ്രവർത്തിക്കൽ)." (ദ,ന)', 'عُمَيْرِ بْنِ قَتَادَةَ', 'ഉമൈറുബ്നു ഖതാദ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ خَبَّابٍ رَضِيَ اللهُ عَنْهُ قَالَ: مُصْعَبُ بْنُ عُمَيْرٍ قُتِلَ يَوْمَ أُحُدٍ، وَلَمْ تَكُنْ لَهُ إِلَّا نَمِرَةٌ: كُنَّا إِذَا غَطَّيْنَا بِهَا رَأْسَهُ خَرَجَتْ رِجْلَاهُ، وَإِذَا غَطَّيْنَا رِجْلَيْهِ خَرَجَ رَأْسُهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "غَطُّوا بِهَا رَأْسَهُ، وَاجْعَلُوا عَلَى رِجْلَيْهِ مِنَ الْإِذْخِرِ". (ق,د,ت,ن)', 'ഖബ്ബാബ്(റ): ഉഹ്ദ് ദിവസം മുസ്അബുബ്നു ഉമൈർ(റ) വധിക്കപ്പെട്ടു. അദ്ദേഹത്തിനാണെങ്കിൽ ഒരു പുതപ്പല്ലാതെ മറ്റൊന്നും ഉണ്ടായിരുന്നില്ല. അതുപയോഗിച്ച് ഞങ്ങൾ അദ്ദേഹത്തിന്റെ തല മൂടിയാൽ അദ്ദേഹത്തിന്റെ കാലുകൾ രണ്ടും പുറത്താകും, അദ്ദേഹത്തിന്റെ കാലുകൾ മൂടിയാൽ തല പുറത്താകും. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതുമായി നിങ്ങൾ അദ്ദേഹത്തിന്റെ തല മൂടുക, അദ്ദേഹത്തിന്റെ കാലുകളിൽ ഇദ്ഖിർ എന്ന പുല്ല് വെക്കുകയും ചെയ്യുക." (ബു,മു,ദ,തു,ന)', 'خَبَّابٍ', 'ഖബ്ബാബ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجَ رَجُلٌ مِنْ بَنِي سَهْمٍ مَعَ تَمِيمٍ الدَّارِيِّ وَعَدِيِّ بْنِ بَدَّاءٍ، فَمَاتَ السَّهْمِيُّ بِأَرْضٍ لَيْسَ بِهَا مُسْلِمٌ، فَلَمَّا قَدِمَا بِتَرِكَتِهِ فَقَدُوا جَامًا مِنْ فِضَّةٍ مُخَوَّصًا مِنْ ذَهَبٍ، فَأَحْلَفَهُمَا رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ وُجِدَ الْجَامُ بِمَكَّةَ، فَقَالُوا: ابْتَعْنَاهُ مِنْ تَمِيمٍ وَعَدِيٍّ. فَقَامَ رَجُلَانِ مِنْ أَوْلِيَاءِ السَّهْمِيِّ، فَحَلَفَا لَشَهَادَتُنَا أَحَقُّ مِنْ شَهَادَتِهِمَا، وَإِنَّ الْجَامَ لِصَاحِبِهِمْ، قَالَ: وَفِيهِمْ نَزَلَتْ هَذِهِ الْآيَةُ: {يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ}. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): ബനൂസഹ്മിൽപെട്ട ഒരാൾ അദിയ്യുബ്നു ബദ്ദാഅ്(റ), തമീമുദ്ദാരി(റ) എന്നിവർക്കൊപ്പം യാത്ര പുറപ്പെട്ടു. അങ്ങനെ മുസ്ലിംകളാരുമില്ലാത്ത ഒരു നാട്ടിൽവെച്ച് സഹ്മുകാരൻ മരണപ്പെട്ടു. ശേഷം അദ്ദേഹത്തിന്റെ അനന്തരസ്വത്തുമായി അവർ രണ്ടുപേരും മടങ്ങിവന്നപ്പോൾ, സ്വർണ്ണം പൂശപ്പെട്ട ഒരു വെള്ളിപ്പാത്രം അവരിൽ നിന്നും നഷ്ടപ്പെട്ടു. റസൂൽ(സ) അവരിവരേയും സത്യംചെയ്യിച്ചു. ശേഷം ആ പാത്രം മക്കയിൽ കണ്ടെത്തി. അവർ (പാത്രം കൈവശം വെച്ചിരുന്നവർ) പറഞ്ഞു: ഞങ്ങൾ തമീമിൽ നിന്നും അദ്യിൽ നിന്നും വാങ്ങിയതാണത്. അപ്പോൾ സഹ്മിയുടെ അവകാശികളിൽപെട്ട രണ്ടാളുകൾ എഴുന്നേറ്റു നിൽക്കുകയും അവരിരുവരുടേയും സാക്ഷിത്വത്തേക്കാൾ ബന്ധപ്പെട്ടത് ഞങ്ങളുടെ സാക്ഷിത്വമാണെന്നും ആ പാത്രം തങ്ങളുടെ ആളുടേതാണെന്നും സത്യംചെയ്യുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: അവരുടെ വിഷയത്തിലാണ് ഈ സൂക്തം അവതരിച്ചത്: ''ഓ സത്യവിശ്വാസികളേ, നിങ്ങളിലൊരുത്തന് മരണമാസന്നമായാൽ നിങ്ങൾക്കിടയിലെ സാക്ഷിത്വം.'' (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 703, 704, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: أَصَبْتُ أَرْضًا مِنْ أَرْضِ خَيْبَرَ، فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: أَصَبْتُ أَرْضًا، لَمْ أُصِبْ مَالًا أَحَبَّ إِلَيَّ وَلَا أَنْفَسَ عِنْدِي مِنْهَا. قَالَ: "إِنْ شِئْتَ تَصَدَّقْتَ بِهَا". فَتَصَدَّقَ بِهَا – عَلَى أَنْ لَا تُبَاعَ وَلَا تُوهَبَ – فِي الْفُقَرَاءِ وَذِي الْقُرْبَى وَالرِّقَابِ وَالضَّيْفِ وَابْنِ السَّبِيلِ، لَا جُنَاحَ عَلَى مَنْ وَلِيَهَا أَنْ يَأْكُلَ بِالْمَعْرُوفِ، غَيْرَ مُتَمَوِّلٍ مَالًا، وَيُطْعِمَ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=65), 1, 'وَفِي رِوَايَةٍ قَالَ: أَصَابَ عُمَرُ أَرْضًا بِخَيْبَرَ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَصَبْتُ أَرْضًا لَمْ أُصِبْ مَالًا قَطُّ أَنْفَسَ عِنْدِي، فَكَيْفَ تَأْمُرُ بِهِ؟ قَالَ: "إِنْ شِئْتَ حَبَّسْتَ أَصْلَهَا وَتَصَدَّقْتَ بِهَا". فَتَصَدَّقَ بِهَا – عَلَى أَنْ لَا تُبَاعَ وَلَا تُوهَبَ وَلَا تُورَثَ – فِي الْفُقَرَاءِ وَالْقُرْبَى وَالرِّقَابِ وَفِي سَبِيلِ اللهِ وَالضَّيْفِ وَابْنِ السَّبِيلِ، لَا جُنَاحَ عَلَى مَنْ وَلِيَهَا أَنْ يَأْكُلَ مِنْهَا بِالْمَعْرُوفِ، وَيُطْعِمَ صَدِيقًا، غَيْرَ مُتَمَوِّلٍ فِيهِ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: ഇബ്നുഉമർ(റ) പറഞ്ഞു: ഉമർ(റ)വിന് ഖൈബറിൽ ഒരു ഭൂമി ലഭിച്ചു. അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: എനിക്കൊരു ഭൂമി ലഭിച്ചിരിക്കുന്നു, അതിനേക്കാൾ എന്റെ പക്കൽ വിലയേറിയ ഒരു മുതലും എനിക്ക് കിട്ടിയിട്ടില്ല. അതിന്റെ കാര്യത്തിൽ അവിടന്നെന്താണ് കൽപിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "നീ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ അതിന്റെ അടിത്തറ വഖ്ഫ് ചെയ്ത് അത് ദാനം ചെയ്തുകൊള്ളുക." അങ്ങനെ വിൽക്കപ്പെടുകയോ ദാനം നൽകപ്പെടുകയോ അനന്തരമെടുക്കപ്പെടുകയോ ചെയ്യരുതെന്ന നിബന്ധനയോടെ, ദരിദ്രർ, കുടുംബക്കാർ, അടിമകൾ, അതിഥികൾ, യാത്രക്കാരൻ എന്നിവർക്കും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലുമായി ഉമർ(റ) അത് ദാനം ചെയ്തു. അതിന്റെ ഉത്തരവാദിത്തമുള്ളവന്, മൂല്യവത്തല്ലാത്തത് അതിൽനിന്ന് നല്ലരീതിയിൽ ഭക്ഷിക്കുകയോ സൂഹൃത്തിന് ഭക്ഷിപ്പിക്കുകയോ ചെയ്യുന്നതൽ പ്രശ്നമില്ല. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ يَحْيَى بْنِ سَعِيدٍ – عَنْ صَدَقَةِ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ – قَالَ: نَسَخَهَا لِي عَبْدُ الْحَمِيدِ بْنُ عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ: بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، هَذَا مَا كَتَبَ عَبْدُ اللَّهِ عُمَرُ فِي ثَمْغٍ، فَقَصَّ مِنْ خَبَرِهِ نَحْوَ حَدِيثِ نَافِعٍ قَالَ: غَيْرَ مُتَأَثِّلٍ مَالًا، فَمَا عَفَا عَنْهُ مِنْ ثَمَرِهِ فَهُوَ لِلسَّائِلِ وَالْمَحْرُومِ، قَالَ: وَسَاقَ الْقِصَّةَ، قَالَ: وَإِنْ شَاءَ وَلِيُّ ثَمْغٍ اشْتَرَى مِنْ ثَمَرِهِ رَقِيقًا لِعَمَلِهِ، وَكَتَبَ مُعَيْقِيبٌ، وَشَهِدَ عَبْدُ اللَّهِ بْنُ الْأَرْقَمِ: بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، هَذَا مَا أَوْصَى بِهِ عَبْدُ اللَّهِ عُمَرُ أَمِيرُ الْمُؤْمِنِينَ إِنْ حَدَثَ بِهِ حَدَثٌ: أَنَّ ثَمْغًا وَصِرْمَةَ بْنِ الْأَكْوَعِ وَالْعَبْدَ الَّذِي فِيهِ، وَالْمِائَةَ سَهْمٍ الَّتِي بِخَيْبَرَ وَرَقِيقَهُ الَّذِي فِيهِ، وَالْمَائَةَ الَّتِي أَطْعَمَهُ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْوَادِي، تَلِيهِ حَفْصَةُ مَا عَاشَتْ، ثُمَّ يَلِيهِ ذُو الرَّأْيِ مِنْ أَهْلِهَا: أَنْ لَا يُبَاعَ وَلَا يُشْتَرَى، يُنْفِقُهُ حَيْثُ رَأَى مِنَ السَّائِلِ وَالْمَحْرُومِ وَذَوِي الْقُرْبَى، وَلَا حَرَجَ عَلَى مَنْ وَلِيَهُ إِنْ أَكَلَ أَوْ آكَلَ أَوِ اشْتَرَى رَقِيقًا مِنْهُ. (د)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന്റെ ദാനത്തെക്കുറിച്ച് യഹ്യബ്നു സഈദ്(റ): അക്കാര്യം അബ്ദുൽ ഹമീദുബ്നു അബ്ദുല്ലാഹിബ്നു അബ്ദുല്ലാഹിബ്നു ഉമറുബ്നുൽ ഖത്താബ്(റ) എനിക്ക് എഴുതിത്തന്നു: പരമകാരുണികനും കരുണാനിധിയുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ, സംഇലെ തോട്ടത്തെക്കുറിച്ച് അല്ലാഹുവിന്റെ ദാസനായ ഉമർ രേഖപ്പെടുത്തുന്നതാണിത്. ശേഷം അദ്ദേഹം മുന്നത്തെ ഹദീസിലുള്ളതുപോലെ സംഭവം വിവരിച്ചു. അദ്ദേഹം പറഞ്ഞു: (സ്വന്തത്തിനായി) മുതൽ സംഭരിക്കാതെ (നടത്തിപ്പുകാരന് അതിൽനിന്ന് ഭക്ഷിക്കുന്നതിൽ പ്രശ്നമില്ല). ഇനി വല്ല പഴവും ബാക്കിവരികയാണെങ്കിൽ അത് യാചകന്നും ഗതിയില്ലാത്തവന്നും ഉള്ളതാണ്. നിവേദകൻ പറയുന്നു: ശേഷം അദ്ദേഹം ആ സംഭവം മുഴുവൻ വിവരിച്ചു. ഉമർ(റ) പറഞ്ഞു: സംഇന്റെ നടത്തിപ്പുകാരന് വേണമെങ്കിൽ അതിലെ പഴം കൊണ്ട്, ജോലിക്കുവേണ്ടി ഒരു അടിമയെ വാങ്ങാം. അബ്ദുല്ലാഹിബ്നുൽ അർഖമിനെ സാക്ഷിനിർത്തിക്കൊണ്ട് മുഐഖീബ് ഇപ്രകാരം എഴുതി: പരമകാരുണികനും കരുണാനിധിയുമായ അല്ലാഹുവിന്റെ നാമത്തിൽ, അല്ലാഹുവിന്റെ ദാസനും സത്യവിശ്വാസികളുടെ നേതാവുമായ ഉമർ, തനിക്ക് വല്ല വിപത്തും സംഭവിക്കുകയാണെങ്കിൽ, വസ്വിയ്യത്ത് ചെയ്യുന്ന കാര്യമാണിത്: സംഇലെ തോട്ടവും, ഇബ്നുൽ അക്വഇന്റെ ഒട്ടകക്കൂട്ടവും, അതിലുള്ള അടിമയും, ഖൈബറിലെ നൂറ് ഓഹരിയും, അതിലുള്ള തന്റെ അടിമയും, മുഹമ്മദ്(സ) അദ്ദേഹത്തിന് ഭക്ഷണത്തിനായി മലഞ്ചെരുവിൽ നൽകിയ നൂറ് ഓഹരിയുമെല്ലാം, വിൽക്കപ്പെടുകയോ വാങ്ങപ്പെടുകയോ ചെയ്യരുതെന്ന നിബന്ധനയോടെ, ഹഫ്സ(റ) തന്റെ ജീവിതകാലം മുഴുവൻ സംരക്ഷിക്കേണ്ടതാണ്. ശേഷം അവരുടെ കുടുംബത്തിലെ മുതിർന്നയാൾ അവ ഏറ്റെടുക്കണം. യാചകന്നോ, ഗതിയില്ലാത്തവന്നോ, കുടുംബക്കാർക്കോ തന്റെ അഭിപ്രായമനുസരിച്ച് (അതിന്റെ സംരക്ഷകൻ) അത് ചെലവഴിക്കണം. അവയുടെ ചുമതല ഏറ്റെടുക്കുന്നവന്, അതിൽനിന്ന് ഭക്ഷിക്കുകയോ ഭക്ഷിപ്പിക്കുകയോ അതുപയോഗിച്ച് അടിമയെ വാങ്ങുകയോ ചെയ്യുന്നതിൽ പ്രശ്നമില്ല. (ദ)', 'يَحْيَى بْنِ سَعِيدٍ – عَنْ صَدَقَةِ عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 705, 705, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَاهُ تَصَدَّقَ بِمَالٍ لَهُ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ يُقَالُ لَهُ ثَمْغٌ، وَكَانَ نَخْلًا، فَقَالَ عُمَرُ: يَا رَسُولَ اللهِ، إِنِّي اسْتَفَدْتُ مَالًا، وَهُوَ عِنْدِي نَفِيسٌ، فَأَرَدْتُ أَنْ أَتَصَدَّقَ بِهِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَصَدَّقْ بِأَصْلِهِ، لَا يُبَاعُ وَلَا يُوهَبُ وَلَا يُورَثُ، وَلَكِنْ يُنْفَقُ ثَمَرُهُ". فَتَصَدَّقَ بِهِ عُمَرُ. فَصَدَقَتُهُ تِلْكَ فِي سَبِيلِ اللَّهِ وَفِي الرِّقَابِ وَالْمَسَاكِينِ وَالضَّيْفِ وَابْنِ السَّبِيلِ وَلِذِي الْقُرْبَى، وَلَا جُنَاحَ عَلَى مَنْ وَلِيَهُ أَنْ يَأْكُلَ مِنْهُ بِالْمَعْرُوفِ أَوْ يُوكِلَ صَدِيقَهُ غَيْرَ مُتَمَوِّلٍ بِهِ. (خ)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് അദ്ദേഹത്തിന്റെ പിതാവ് തന്റെ ഒരു മുതൽ ദാനംചെയ്തു. അത് സംഅ് എന്ന് പേരുള്ള ഒരു ഈത്തപ്പനത്തോട്ടമായിരുന്നു. ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാനൊരു സമ്പത്ത് കരഗതമാക്കിയിട്ടുണ്ട്. അത് എന്റെ പക്കൽ വിലപ്പെട്ടതാണ്. അത് ദാനം ചെയ്യണമെന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അടിസ്ഥാനപരമായിത്തന്നെ നീ അതിനെ ദാനം ചെയ്യുക. അത് വിൽക്കപ്പെടുകയോ, വെറുതെ നൽകപ്പെടുകയോ, അനന്തരമെടുക്കപ്പെടുകയോ ചെയ്യരുത്. എന്നാൽ അതിലെ ഫലങ്ങൾ ചെലവഴിക്കപ്പെടണം." അങ്ങനെ ഉമർ(റ) അത് ദാനം ചെയ്തു. അദ്ദേഹത്തിന്റെ ആ ദാനം അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിലും, അടിമകൾ, ദരിദ്രർ, അതിഥികൾ, യാത്രക്കാർ, കുടുംബബന്ധമുള്ളവർ എന്നിവർക്ക് വേണ്ടിയും ആയിരുന്നു. അതിന്റെ ഉത്തരവാദിത്തമുള്ളവന് അതിൽനിന്ന് നല്ലരീതിയിൽ ഭക്ഷിക്കുകയോ മൂല്യവത്തല്ലാത്തത് തന്റെ സുഹൃത്തിന് ഭക്ഷിപ്പിക്കുകയോ ചെയ്യുന്നതൽ പ്രശ്നമില്ല. (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 705, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ: {لَنْ تَنَالُوا الْبِرَّ حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ} [آل عمران: ٩٢] قَالَ أَبُو طَلْحَةَ رَضِيَ اللهُ عَنْهُ: إِنَّ رَبَّنَا لَيَسْأَلُنَا عَنْ أَمْوَالِنَا، فَأُشْهِدُكَ يَا رَسُولَ اللهِ أَنِّي قَدْ جَعَلْتُ أَرْضِي لِلَّهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اجْعَلْهَا فِي قَرَابَتِكَ: فِي حَسَّانَ بْنِ ثَابِتٍ وَأُبَيِّ بْنِ كَعْبٍ". (ن)', 'അനസ്(റ): ''നിങ്ങൾ ഇഷ്ടപ്പെടുന്നതിൽ നിന്നും ചെലവഴിക്കുന്നതുവരെ നിങ്ങൾ സത്യവിശ്വാസികളാവുകയില്ല.'' (ആലുഇംറാൻ: 92) എന്ന സൂക്തം അവതരിച്ചപ്പോൾ അബൂത്വൽഹ(റ) പറഞ്ഞു: നിശ്ചയം നമ്മുടെ രക്ഷിതാവ് നമ്മുടെ സമ്പത്തിനെക്കുറിച്ച് ചോദിക്കുകതന്നെ ചെയ്യും. അതിനാൽ എന്റെ ഭൂമി അല്ലാഹുവിന് നൽകുന്നുവെന്നതിന്, അല്ലഹുവിന്റെ റസൂലേ, ഞാനിതാ അങ്ങയെ സാക്ഷിയാക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അത് നിന്റെ കുടുംബങ്ങളായ ഹസ്സാനുബ്നു സാബിതിനും ഉബയ്യുബ്നു കഅ്ബിനുമായി നിശ്ചയിക്കുക." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], 'آل عمران: ٩٢', null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا – عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ – قَالَ: جَاءَ عُمَرُ إِلَى رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي أَصَبْتُ مَالًا لَمْ أُصِبْ مِثْلَهُ قَطُّ، كَانَ لِي مِائَةُ رَأْسٍ فَاشْتَرَيْتُ بِهَا مِائَةَ سَهْمٍ مِنْ خَيْبَرَ مِنْ أَهْلِهَا، وَإِنِّي قَدْ أَرَدْتُ أَنْ أَتَقَرَّبَ بِهَا إِلَى اللَّهِ عَزَّ وَجَلَّ. قَالَ: "فَاحْبِسْ أَصْلَهَا وَسَبِّلِ الثَّمَرَةَ". (ن)', 'ഉമർ(റ)വിൽനിന്ന് ഇബ്നുഉമർ(റ): ഉമർ(റ) റസൂൽ(സ)യുടെ അടുത്ത്വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എനിക്കൊരു സമ്പത്ത് ലഭിച്ചിരിക്കുന്നു, അതുപോലൊരു സമ്പത്ത് എനിക്ക് ലഭിച്ചിട്ടില്ല. എനിക്ക് നൂറ് മൃഗങ്ങളുണ്ടായിരുന്നു. അതുപയോഗിച്ച് ഞാൻ ഖൈബറുകാരിൽ നിന്ന് നൂറ് ഓഹരി വാങ്ങി. അത് അല്ലാഹുവിലേക്കടുക്കാനുള്ള പുണ്ണ്യമായിട്ട് ദാനം ചെയ്യാൻ ഞാൻ ആഗ്രഹിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അതിന്റെ അടിത്തറ വഖ്ഫ് ചെയ്ത് അതിലുള്ള ഫലങ്ങൾ നീ യാത്രക്കാർക്കുവേണ്ടിയുള്ളതാക്കുക." (ന)', 'ابْنِ عُمَرَ', 'ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنِ الْأَحْنَفِ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ الْمَدِينَةَ وَأَنَا حَاجٌّ، فَبَيْنَا نَحْنُ فِي مَنَازِلِنَا نَضَعُ رِحَالَنَا إِذْ أَتَى آتٍ فَقَالَ: قَدِ اجْتَمَعَ النَّاسُ فِي الْمَسْجِدِ، فَاطَّلَعْتُ فَإِذَا النَّاسُ مُجْتَمِعُونَ، وَإِذَا بَيْنَ أَظْهُرِهِمْ نَفَرٌ قُعُودٌ، فَإِذَا هُوَ عَلِيُّ بْنُ أَبِي طَالِبٍ وَالزُّبَيْرُ وَطَلْحَةُ وَسَعْدُ بْنُ أَبِي وَقَّاصٍ، رَحْمَةُ اللَّهِ عَلَيْهِمْ، فَلَمَّا قُمْتُ عَلَيْهِمْ قِيلَ: هَذَا عُثْمَانُ بْنُ عَفَّانَ قَدْ جَاءَ. قَالَ: فَجَاءَ وَعَلَيْهِ مُلَيَّةٌ – مُلَاءَةٌ – صَفْرَاءُ، قَدْ قَنَعَ رَأْسَهُ بِهَا. فَقُلْتُ لِصَاحِبِي: كَمَا أَنْتَ حَتَّى أَنْظُرَ مَا جَاءَ بِهِ. فَقَالَ عُثْمَانُ: أَهَاهُنَا عَلِيٌّ؟ أَهَاهُنَا الزُّبَيْرُ؟ أَهَاهُنَا طَلْحَةُ؟ أَهَاهُنَا سَعْدٌ؟ قَالُوا: نَعَمْ. قَالَ: فَأَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ يَبْتَاعُ مِرْبَدَ بَنِي فُلَانٍ غَفَرَ اللَّهُ لَهُ". فَابْتَعْتُهُ – وَفِي رِوَايَةٍ: بِعِشْرِينَ أَلْفًا، أَوْ بِخَمْسَةٍ وَعِشْرِينَ أَلْفًا – فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: إِنِّي ابْتَعْتُ مِرْبَدَ بَنِي فُلَانٍ، قَالَ: "فَاجْعَلْهُ فِي مَسْجِدِنَا وَأَجْرُهُ لَكَ". قَالُوا: نَعَمْ. قَالَ: فَأَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، هَلْ تَعْلَمُونَ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ يَبْتَاعُ بِئْرَ رُومَةَ غَفَرَ اللَّهُ لَهُ". – فِي رِوَايَةٍ: فَابْتَعْتُهَا بِكَذَا – فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: قَدِ ابْتَعْتُ بِئْرَ رُومَةَ. قَالَ: "فَاجْعَلْهَا سِقَايَةً لِلْمُسْلِمِينَ وَأَجْرُهَا لَكَ". قَالُوا: نَعَمْ. قَالَ: فَأَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، هَلْ تَعْلَمُونَ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – وَفِي رِوَايَةٍ: نَظَرَ فِي وُجُوهِ الْقَوْمِ فَقَالَ: "مَنْ جَهَّزَ هَؤُلَاءِ". – قَالَ: "مَنْ يُجَهِّزُ جَيْشَ الْعُسْرَةِ غَفَرَ اللَّهُ لَهُ". فَجَهَّزْتُهُمْ حَتَّى مَا يَفْقِدُونَ عِقَالًا وَلَا خِطَامًا. قَالُوا: نَعَمْ. قَالَ: اللَّهُمَّ اشْهَدْ، اللَّهُمَّ اشْهَدْ، اللَّهُمَّ اشْهَدْ. (ن)', 'അഹ്നഫുബ്നു ഖൈസ്(റ): ഹജ്ജുകാരനായിരിക്കെ ഞാൻ മദീനയിൽ ചെന്നു. അങ്ങനെ ഞങ്ങൾ ഞങ്ങളുടെ കൂടാരങ്ങളിൽ ഒട്ടകക്കട്ടിലുകൾ ഇറക്കിവെച്ചുകൊണ്ടിരിക്കെ ഒരാൾ വന്ന് പറഞ്ഞു: ജനങ്ങളിതാ പള്ളിയിൽ ഒരുമിച്ചുകൂടിയിരിക്കുന്നു. ഞാൻ എത്തിനോക്കിയപ്പോൾ ജനങ്ങളെല്ലാം ഒരുമിച്ചുകൂടിയതായി കണ്ടു. അവർക്കിടയിൽ ഇരിക്കുന്ന ഒരു കൂട്ടരുമുണ്ട്. അലിയ്യുബ്നു അബീത്വാലിബ്(റ), സൂബൈർ(റ), ത്വൽഹത്(റ), സഅ്ദുബ്നു അബീവഖാസ്(റ) എന്നിവരായിരുന്നു അത്. ഞാൻ അവരിലേക്ക് എഴുന്നേറ്റ് ചെന്നപ്പോൾ പറയപ്പെട്ടു: ഇതാ, ഉസ്മാനുബ്നു അഫ്ഫാൻ(റ) വന്നിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഉസ്മാൻ(റ) വന്നു. അദ്ദേഹത്തിനുമേൽ മഞ്ഞ നിറത്തിലുള്ള ഒരു മേൽവസ്ത്രവുമുണ്ടായിരുന്നു. അതുമായി അദ്ദേഹം തന്റെ തല മൂടിയിട്ടുണ്ട്. അപ്പോൾ ഞാനെന്റെ കൂട്ടുകാരനോട് പറഞ്ഞു: അദ്ദേഹം എന്തിനാണ് വന്നതെന്ന് ഞാൻ കാണുന്നതുവരെ നീ അങ്ങനെത്തന്നെ നിൽക്കുക. ഉസ്മാൻ(റ) ചോദിച്ചു: ഇവിടെ അലി(റ)വുണ്ടോ? ഇവിടെ സൂബൈർ(റ)വുണ്ടോ? ഇവിടെ ത്വൽഹ(റ)വുണ്ടോ? ഇവിടെ സഅ്ദ്(റ)വുണ്ടോ? ജനങ്ങൾ പറഞ്ഞു: അതെ. ഉസ്മാൻ(റ) പറഞ്ഞു: എങ്കിൽ അല്ലാഹുവിനെക്കൊണ്ട് - അവനല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല - സത്യം ചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: റസൂൽ(സ) പറഞ്ഞു: "ഇന്ന കുടുംബത്തിന്റെ മെതിക്കളം വാങ്ങുന്നവന്ന് അല്ലാഹു പൊറുത്തുകൊടുക്കട്ടെ." അപ്പോൾ ഞാനത് വാങ്ങി. - മറ്റൊരു നിവേദനത്തിൽ: ഇരുപതിനായിരത്തിന്, അല്ലെങ്കിൽ ഇരുപത്തയ്യായിരത്തിന് (വാങ്ങി) - ശേഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: ആ കുടുംബത്തിന്റെ മെതിക്കളം ഞാൻ വാങ്ങിയിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതിനെ നമ്മുടെ പള്ളിയിൽ ചേർക്കുക, അതിന്റെ പ്രതിഫലം നിനക്കായിരിക്കും." ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ട് - അവനല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല - സത്യം ചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: റസൂൽ(സ) പറഞ്ഞു: "റൂമ കിണർ വാങ്ങുന്നവന്ന് അല്ലാഹു പൊറുത്തുകൊടുക്കട്ടെ." - മറ്റൊരു നിവേദനം: അപ്പോൾ ഇത്രയും ഇത്രയും നൽകി ഞാനത് വാങ്ങി - ശേഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്തുചെന്ന് പറഞ്ഞു: റൂമാ കിണർ ഞാൻ വാങ്ങിയിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അതിനെ നീ മുസ്ലിംകൾക്ക് വെള്ളം കുടിക്കാനുള്ള സ്ഥലമാക്കുക. അതിന്റെ പ്രതിഫലം നിനക്കായിരിക്കും." ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ട് - അവനല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല - സത്യം ചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: നിശ്ചയം - മറ്റൊരു നിവേദനം: റസൂൽ(സ) ജനങ്ങളുടെ മുഖത്ത് നോക്കിയിട്ട് പറഞ്ഞു: "ഇവരെ (യുദ്ധത്തിനായി) സജ്ജമാക്കുന്നവന്" - റസൂൽ(സ) പറഞ്ഞു: "പ്രയാസമനുഭവിക്കുന്ന (യുദ്ധസാമഗ്രികളില്ലാത്ത) സൈന്യത്തെ സജ്ജീകരിക്കുന്ന വ്യക്തിക്ക് അല്ലാഹു പൊറുത്തുകൊടുക്കട്ടെ." അപ്പോൾ ഒരു മൂക്കയറോ ഒട്ടകക്കയറോ പോലും കുറവില്ലാത്ത വിധം ഞാനവരെ സജ്ജീകരിച്ചു. ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവേ, നീ സാക്ഷിയാവുക. അല്ലാഹുവേ, നീ സാക്ഷിയാവുക. അല്ലാഹുവേ, നീ സാക്ഷിയാവുക. (ന)', 'الْأَحْنَفِ بْنِ قَيْسٍ', 'അഹ്നഫുബ്നു ഖൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 707, 708, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=70), 1, 'وَفِي رِوَايَةٍ: بِعِشْرِينَ أَلْفًا، أَوْ بِخَمْسَةٍ وَعِشْرِينَ أَلْفًا – فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: إِنِّي ابْتَعْتُ مِرْبَدَ بَنِي فُلَانٍ، قَالَ: "فَاجْعَلْهُ فِي مَسْجِدِنَا وَأَجْرُهُ لَكَ". قَالُوا: نَعَمْ. قَالَ: فَأَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، هَلْ تَعْلَمُونَ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ يَبْتَاعُ بِئْرَ رُومَةَ غَفَرَ اللَّهُ لَهُ". – فِي رِوَايَةٍ: فَابْتَعْتُهَا بِكَذَا – فَأَتَيْتُ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: قَدِ ابْتَعْتُ بِئْرَ رُومَةَ. قَالَ: "فَاجْعَلْهَا سِقَايَةً لِلْمُسْلِمِينَ وَأَجْرُهَا لَكَ". قَالُوا: نَعَمْ. قَالَ: فَأَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، هَلْ تَعْلَمُونَ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ –', 'മറ്റൊരു നിവേദനത്തിൽ: ഇരുപതിനായിരത്തിന്, അല്ലെങ്കിൽ ഇരുപത്തയ്യായിരത്തിന് (വാങ്ങി) - ശേഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: ആ കുടുംബത്തിന്റെ മെതിക്കളം ഞാൻ വാങ്ങിയിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതിനെ നമ്മുടെ പള്ളിയിൽ ചേർക്കുക, അതിന്റെ പ്രതിഫലം നിനക്കായിരിക്കും." ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ട് - അവനല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല - സത്യം ചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: റസൂൽ(സ) പറഞ്ഞു: "റൂമ കിണർ വാങ്ങുന്നവന്ന് അല്ലാഹു പൊറുത്തുകൊടുക്കട്ടെ." -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=70), 2, 'وَفِي رِوَايَةٍ: نَظَرَ فِي وُجُوهِ الْقَوْمِ فَقَالَ: "مَنْ جَهَّزَ هَؤُلَاءِ". – قَالَ: "مَنْ يُجَهِّزُ جَيْشَ الْعُسْرَةِ غَفَرَ اللَّهُ لَهُ". فَجَهَّزْتُهُمْ حَتَّى مَا يَفْقِدُونَ عِقَالًا وَلَا خِطَامًا. قَالُوا: نَعَمْ. قَالَ: اللَّهُمَّ اشْهَدْ، اللَّهُمَّ اشْهَدْ، اللَّهُمَّ اشْهَدْ. (ن)', 'മറ്റൊരു നിവേദനം: അപ്പോൾ ഇത്രയും ഇത്രയും നൽകി ഞാനത് വാങ്ങി - ശേഷം ഞാൻ റസൂൽ(സ)യുടെ അടുത്തുചെന്ന് പറഞ്ഞു: റൂമാ കിണർ ഞാൻ വാങ്ങിയിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അതിനെ നീ മുസ്ലിംകൾക്ക് വെള്ളം കുടിക്കാനുള്ള സ്ഥലമാക്കുക. അതിന്റെ പ്രതിഫലം നിനക്കായിരിക്കും." ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ട് - അവനല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല - സത്യം ചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: നിശ്ചയം -');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=3 and b.book_no=12 and h.hadith_no=70), 3, null, 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) ജനങ്ങളുടെ മുഖത്ത് നോക്കിയിട്ട് പറഞ്ഞു: "ഇവരെ (യുദ്ധത്തിനായി) സജ്ജമാക്കുന്നവന്" - റസൂൽ(സ) പറഞ്ഞു: "പ്രയാസമനുഭവിക്കുന്ന (യുദ്ധസാമഗ്രികളില്ലാത്ത) സൈന്യത്തെ സജ്ജീകരിക്കുന്ന വ്യക്തിക്ക് അല്ലാഹു പൊറുത്തുകൊടുക്കട്ടെ." അപ്പോൾ ഒരു മൂക്കയറോ ഒട്ടകക്കയറോ പോലും കുറവില്ലാത്ത വിധം ഞാനവരെ സജ്ജീകരിച്ചു. ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവേ, നീ സാക്ഷിയാവുക. അല്ലാഹുവേ, നീ സാക്ഷിയാവുക. അല്ലാഹുവേ, നീ സാക്ഷിയാവുക. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ ثُمَامَةَ بْنِ حَزْنٍ الْقُشَيْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: شَهِدْتُ الدَّارَ حِينَ أَشْرَفَ عَلَيْهِمْ عُثْمَانُ رَضِيَ اللهُ عَنْهُ فَقَالَ: أَنْشُدُكُمْ بِاللَّهِ وَبِالْإِسْلَامِ، هَلْ تَعْلَمُونَ: أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِمَ الْمَدِينَةَ وَلَيْسَ بِهَا مَاءٌ يُسْتَعْذَبُ غَيْرَ بِئْرِ رُومَةَ، فَقَالَ: "مَنْ يَشْتَرِي بِئْرَ رُومَةَ، فَيَجْعَلُ فِيهَا دَلْوَهُ مَعَ دِلَاءِ الْمُسْلِمِينَ بِخَيْرٍ لَهُ مِنْهَا فِي الْجَنَّةِ". فَاشْتَرَيْتُهَا مِنْ صُلْبِ مَالِي، فَجَعَلْتُ دَلْوِي فِيهَا مَعَ دِلَاءِ الْمُسْلِمِينَ، وَأَنْتُمُ الْيَوْمَ تَمْنَعُونِي مِنَ الشُّرْبِ مِنْهَا، حَتَّى أَشْرَبَ مِنْ مَاءِ الْبَحْرِ؟ قَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: فَأَنْشُدُكُمْ بِاللَّهِ وَالْإِسْلَامِ، هَلْ تَعْلَمُونَ أَنِّي جَهَّزْتُ جَيْشَ الْعُسْرَةِ مِنْ مَالِي؟ قَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: فَأَنْشُدُكُمْ بِاللَّهِ وَالْإِسْلَامِ، هَلْ تَعْلَمُونَ أَنَّ الْمَسْجِدَ ضَاقَ بِأَهْلِهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ يَشْتَرِي بُقْعَةَ آلِ فُلَانٍ، فَيَزِيدُهَا فِي الْمَسْجِدِ، بِخَيْرٍ لَهُ مِنْهَا فِي الْجَنَّةِ". فَاشْتَرَيْتُهَا مِنْ صُلْبِ مَالِي فَزِدْتُهَا فِي الْمَسْجِدِ، وَأَنْتُمْ تَمْنَعُونِي أَنْ أُصَلِّيَ فِيهِ رَكْعَتَيْنِ؟ قَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: أَنْشُدُكُمْ بِاللَّهِ وَالْإِسْلَامِ، هَلْ تَعْلَمُونَ أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ عَلَى ثَبِيرِ مَكَّةَ، وَمَعَهُ أَبُو بَكْرٍ وَعُمَرُ وَأَنَا، فَتَحَرَّكَ الْجَبَلُ، فَرَكَضَهُ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِرِجْلِهِ وَقَالَ: "اسْكُنْ ثَبِيرُ، فَإِنَّمَا عَلَيْكَ نَبِيٌّ وَصِدِّيقٌ وَشَهِيدَانِ". قَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: اللَّهُ أَكْبَرُ، شَهِدُوا لِي وَرَبِّ الْكَعْبَةِ أَنِّي شَهِيدٌ. (ن)', 'സുമാമതുബ്നു ഹസ്നുൽ ഖുശൈരീ(റ): ഉസ്മാൻ(റ) ജനങ്ങളിലേക്ക് തലയുയർത്തി നോക്കിയ സമയത്ത് ഞാനും ആ വീട്ടിലുണ്ടായിരുന്നു. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ടും ഇസ്ലാമിനെക്കൊണ്ടും സത്യംചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: റൂമാ കിണറല്ലാതെ ശുദ്ധവെള്ളം ലഭിക്കുന്ന മറ്റൊരു കിണറും മദീനയിലില്ലാത്ത സമയത്താണ് റസൂൽ(സ) മദീനയിൽ വന്നതെന്ന് നിങ്ങൾക്കറിയില്ലേ? അങ്ങനെ റസൂൽ(സ) ചോദിച്ചു: "സ്വർഗ്ഗത്തിൽ തനിക്ക് ലഭിക്കാനുള്ള വലിയ നന്മക്കു പകരമായിട്ട് റൂമാ കിണർ വാങ്ങുകയും മുസ്ലിംകളുടെ തൊട്ടികൾക്കൊപ്പം തന്റെ തൊട്ടി അതിലിടുകയും (അത് പൊതുമുതലാക്കുക) ചെയ്യാൻ തയ്യാറുള്ള ആരാണുള്ളത്?" അങ്ങനെ എന്റെ സ്വന്തം മുതലുകൊണ്ട് ഞാനത് വാങ്ങുകയും മുസ്ലിംകളുടെ തൊട്ടികൾക്കൊപ്പം എന്റെ തൊട്ടി അതിലിടുകയും ചെയ്തു. ഇന്ന് നിങ്ങൾ ആ കിണറ്റിൽ നിന്നും കുടിക്കാൻ എന്നെ അനുവദിക്കാതെ ഞാനിതാ കടൽവെള്ളം കുടിക്കുന്നു? അവർ പറഞ്ഞു: അതെ, അല്ലാഹുവാണ് സത്യം (ആ സംഭവം ഞങ്ങൾക്കറിയാം). ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ടും ഇസ്ലാമിനെക്കൊണ്ടും സത്യംചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: പ്രയാസമനുഭവിച്ചിരുന്ന (യുദ്ധസാമഗ്രികളില്ലാത്ത) സൈന്യത്തെ എന്റെ മുതലുപയോഗിച്ച് ഞാൻ സജ്ജീകരിച്ചുവെന്നത് നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ, അല്ലാഹുവാണ് സത്യം. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ടും ഇസ്ലാമിനെക്കൊണ്ടും സത്യംചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: പള്ളിയിൽ ജനങ്ങളെ കൊള്ളാതെ വന്നപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "സ്വർഗ്ഗത്തിൽ തനിക്ക് ലഭിക്കാനുള്ള ഒരു വലിയ നന്മക്ക് പകരമായിട്ട്, ഇന്ന വ്യക്തിയുടെ ഭൂമി വാങ്ങി അത് പള്ളിയിൽ ചേർക്കാൻ തയ്യാറുള്ള ആരാണുള്ളത്?" അപ്പോൾ എന്റെ സ്വന്തം സമ്പത്തുപയോഗിച്ച് ഞാനത് വാങ്ങി പള്ളിയിൽ ചേർത്തുവെന്ന കാര്യം നിങ്ങൾക്കറിയില്ലേ? ഇന്നിതാ ആ പള്ളിയിൽ രണ്ടു റക്അത് നമസ്കരിക്കുന്നതിൽ നിന്നും നിങ്ങൾ എന്നെ തടയുന്നു. അവർ പറഞ്ഞു: അതെ, അല്ലാഹുവാണ് സത്യം (ആ സംഭവം ഞങ്ങൾക്കറിയാം). ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ടും ഇസ്ലാമിനെക്കൊണ്ടും സത്യംചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു: റസൂൽ(സ) മക്കയിലെ സബീർ മല മുകളിൽ നിൽക്കുകയായിരുന്നു. കൂടെ അബൂബക്കർ(റ)വും ഉമർ(റ)വും ഞാനും ഉണ്ടായിരുന്നു. അപ്പോൾ ആ മല ഇളകി. ഉടൻ റസൂൽ(സ) മലയിൽ തന്റെ കാലുകൊണ്ട് ചവിട്ടിയിട്ട് പറഞ്ഞു: "സബീറേ, അടങ്ങിയിരിക്കുക, നിശ്ചയം നിന്റെ മുകളിലുള്ളത് ഒരു നബിയും സിദ്ധീഖും രണ്ടു രക്തസാക്ഷികളുമാണ്." ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ? അവർ പറഞ്ഞു: അതെ, അല്ലാഹുവാണ് സത്യം. ഉസ്മാൻ(റ) പറഞ്ഞു: അല്ലാഹു അക്ബർ (അല്ലാഹുവാണ് വലിയവൻ), കഅ്ബയുടെ രക്ഷിതാവ് തന്നെ സത്യം, ഞാൻ രക്തസാക്ഷിയാണെന്നതിന് അവരിതാ എനിക്ക് സാക്ഷികളായിരിക്കുന്നു. (ന)', 'ثُمَامَةَ بْنِ حَزْنٍ الْقُشَيْرِيِّ', 'സുമാമതുബ്നു ഹസ്നുൽ ഖുശൈരീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 708, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ رَضِيَ اللهُ عَنْهُ: أَنَّ عُثْمَانَ رَضِيَ اللهُ عَنْهُ أَشْرَفَ عَلَيْهِمْ حِينَ حَصَرُوهُ فَقَالَ: أَنْشُدُ بِاللَّهِ رَجُلًا سَمِعَ مِنْ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ يَوْمَ الْجَبَلِ حِينَ اهْتَزَّ، فَرَكَلَهُ بِرِجْلِهِ وَقَالَ: "اسْكُنْ، فَإِنَّهُ لَيْسَ عَلَيْكَ إِلَّا نَبِيٌّ أَوْ صِدِّيقٌ أَوْ شَهِيدَانِ". وَأَنَا مَعَهُ. فَانْتَشَدَ لَهُ رِجَالٌ، ثُمَّ قَالَ: أَنْشُدُ بِاللَّهِ رَجُلًا شَهِدَ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ بَيْعَةِ الرِّضْوَانِ يَقُولُ: "هَذِهِ يَدُ اللَّهِ وَهَذِهِ يَدُ عُثْمَانَ". فَانْتَشَدَ لَهُ رِجَالٌ، ثُمَّ قَالَ: أَنْشُدُ بِاللَّهِ رَجُلًا سَمِعَ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ جَيْشِ الْعُسْرَةِ يَقُولُ: "مَنْ يُنْفِقُ نَفَقَةً مُتَقَبَّلَةً". فَجَهَّزْتُ نِصْفَ الْجَيْشِ مِنْ مَالِي. فَانْتَشَدَ لَهُ رِجَالٌ، ثُمَّ قَالَ: أَنْشُدُ بِاللَّهِ رَجُلًا سَمِعَ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ يَزِيدُ فِي هَذَا الْمَسْجِدِ بِبَيْتٍ فِي الْجَنَّةِ". فَاشْتَرَيْتُهُ مِنْ مَالِي. فَانْتَشَدَ لَهُ رِجَالٌ، ثُمَّ قَالَ: أَنْشُدُ بِاللَّهِ رَجُلًا شَهِدَ رُومَةَ تُبَاعُ، فَاشْتَرَيْتُهَا مِنْ مَالِي فَأَبَحْتُهَا لِابْنِ السَّبِيلِ. فَانْتَشَدَ لَهُ رِجَالٌ. (ن)', 'അബൂസലമതുബ്നു അബ്ദിർറഹ്മാൻ(റ): ജനങ്ങൾ ഉസ്മാൻ(റ)വിനെ ഉപരോധിച്ച സമയത്ത് അദ്ദേഹം ജനങ്ങളിലേക്ക് എത്തിനോക്കിയിട്ട് പറഞ്ഞു: മല ഇളകുകയും അപ്പോൾ റസൂൽ(സ) തന്റെ കാലുകൊണ്ട് അതിൽ ചവിട്ടുകയും ചെയ്ത സംഭവത്തിൽ റസൂൽ(സ) പറയുന്നത് കേട്ട വ്യക്തിയോട് ഞാൻ സത്യംചെയ്ത് ചോദിക്കുന്നു: റസൂൽ(സ) പറഞ്ഞു: "നീ അടങ്ങിനിൽക്കുക, നിശ്ചയം നിന്റെ മുകളിൽ ഒരു നബിയും സിദ്ധീഖും രണ്ട് രക്തസാക്ഷികളും മാത്രമാണുള്ളത്." ഞാനും റസൂൽ(സ)യോടൊപ്പമുണ്ടായിരുന്നു (ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ)? അപ്പോൾ കുറേയാളുകൾ അദ്ദേഹത്തെ ശരിവെച്ചു. ശേഷം ഉസ്മാൻ(റ) പറഞ്ഞു: ബൈഅതുർറിള്വാൻ (രിള്വാൻ ഉടമ്പടി) ദിവസം "ഇത് അല്ലാഹുവിന്റെ കയ്യാണ്, ഇത് ഉസ്മാന്റെ കയ്യാണ്" എന്ന് റസൂൽ(സ) പറയുന്നതിന് സാക്ഷിയായ ആളോട് ഞാൻ സത്യം ചെയ്ത് ചോദിക്കുന്നു (ആ സംഭവം നിങ്ങൾക്കറിയില്ലേ)? അപ്പോൾ കുറേ ആളുകൾ അദ്ദേഹത്തെ ശരിവെച്ചു. ശേഷം ഉസ്മാൻ(റ) പറഞ്ഞു: സൈന്യത്തിന് പ്രയാസമനുഭവപ്പെട്ട ദിവസം "ആരാണ് സ്വീകാര്യമായ ഒരു ദാനം നൽകുക" എന്ന് നബി(സ) ചോദിക്കുന്നത് കേട്ട ആളോട് ഞാൻ സത്യംചെയ്തു ചോദിക്കുന്നു: അപ്പോൾ എന്റെ മുതലുകൊണ്ട് സൈന്യത്തിന്റെ പകുതി ഞാൻ സജ്ജീകരിച്ചു (ആ സംഭവം നിങ്ങൾക്കറിയില്ലേ)? അപ്പോഴും കുറേ ആളുകൾ അദ്ദേഹത്തെ ശരിവെച്ചു. ശേഷം ഉസ്മാൻ(റ) പറഞ്ഞു: "സ്വർഗ്ഗത്തിലെ ഒരു വീടിന്റെയത്ര സ്ഥലം ആരാണ് ഈ പള്ളിയിൽ അധികരിപ്പിക്കുക" എന്ന് റസൂൽ(സ) പറയുന്നത് കേട്ട ആളോട് ഞാൻ സത്യംചെയ്ത് ചോദിക്കുന്നു: അപ്പോൾ എന്റെ മുതലുപയോഗിച്ച് ഞാനത് വാങ്ങി (ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ)? അപ്പോഴും കുറേ ആളുകൾ അദ്ദേഹത്തെ ശരിവെച്ചു. ശേഷം ഉസ്മാൻ(റ) പറഞ്ഞു: റൂമാ കിണർ വിൽക്കപ്പെടുമ്പോൾ അവിടെയുണ്ടായിരുന്ന ആളുകളോട് ഞാൻ സത്യംചെയ്ത് ചോദിക്കുന്നു: ആ സമയം എന്റെ മുതലുപയോഗിച്ച് ഞാനത് വാങ്ങുകയും യാത്രക്കാർക്ക് അത് അനുവദിച്ചുകൊടുക്കുകയും ചെയ്തു (ഈ സംഭവം നിങ്ങൾക്കറിയില്ലേ)? അപ്പോഴും കുറേ ആളുകൾ അദ്ദേഹം പറഞ്ഞത് ശരിവെച്ചു. (ന)', 'أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ', 'അബൂസലമതുബ്നു അബ്ദിർറഹ്മാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 709, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عُثْمَانَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ حِينَ حُوصِرَ: أُنْشِدُكُمُ اللَّهَ وَلَا أُنْشِدُ إِلَّا أَصْحَابَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَلَسْتُمْ تَعْلَمُونَ أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَفَرَ رُومَةَ فَلَهُ الْجَنَّةُ". فَحَفَرْتُهَا، أَلَسْتُمْ تَعْلَمُونَ، أَنَّهُ قَالَ: "مَنْ جَهَّزَ جَيْشَ الْعُسْرَةِ فَلَهُ الْجَنَّةُ". فَجَهَّزْتُهُمْ. فَصَدَّقُوهُ بِمَا قَالَ. (خ)', 'ഉസ്മാൻ(റ): ഉപരോധിക്കപ്പെട്ട സമയത്ത് അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിനെക്കൊണ്ട് സത്യംചെയ്ത് ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു, നബി(സ)യുടെ അനുചരരോട് മാത്രമാണ് ഞാൻ ചോദിക്കുന്നത്: റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞുവെന്ന് നിങ്ങൾക്കറിയില്ലേ: "റൂമാ കിണർ കുഴിക്കുന്നവന് സ്വർഗ്ഗമുണ്ട്." അപ്പോൾ ഞാനത് കുഴിച്ചു. റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞുവെന്ന് നിങ്ങൾക്കറിയില്ലേ: "പ്രയാസപ്പെടുന്ന സൈന്യത്തെ സജ്ജീകരിക്കുന്നവന് സ്വർഗ്ഗമുണ്ട്." ഉടനെ ഞാനവരെ സജ്ജീകരിച്ചു. അപ്പോൾ ഉസ്മാൻ(റ)വിന്റെ വാക്കുകളെ ജനങ്ങൾ ശരിവെച്ചു. (ബു)', 'عُثْمَانَ', 'ഉസ്മാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 710, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=3 and b.book_no=12 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
